import { GoogleGenAI } from "@google/genai";
import { FinancialRecord } from "../types";

export const generateBusinessInsights = async (data: FinancialRecord[]): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

    const summaryData = data.slice(0, 15).map(item => ({
      client: item['nombre cliente'],
      gp: item.GP,
      tons: item.TON,
      ratio: item['% Inversion Lab'] * 100
    }));

    const totalGP = data.reduce((acc, curr) => acc + curr.GP, 0);
    const totalInv = data.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0);
    const globalRatio = totalGP > 0 ? (totalInv / totalGP) * 100 : 0;

    const prompt = `
      Act as a Senior Financial Analyst. Analyze this business performance data:
      - Overall Dataset Count: ${data.length} records.
      - Total Gross Profit (GP): $${totalGP.toLocaleString()}
      - Total Investment: $${totalInv.toLocaleString()}
      - Global Investment Ratio: ${globalRatio.toFixed(2)}%

      Sample Client Performance:
      ${JSON.stringify(summaryData)}

      Please provide:
      1. A concise summary of financial health.
      2. Identification of high-risk clients (where investment ratio > 8%).
      3. Actionable strategic recommendations to improve ROI.

      Format the output using professional Markdown. Keep it brief and high-impact.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Unable to generate insights at this time.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error generating analysis. Please ensure your API key is valid.";
  }
};

import React, { useState, useEffect } from 'react';
import { FinancialRecord } from '../types';
import { MONTHS } from '../utils/dataProcessor';
import { Filter, Upload, RotateCcw, ChevronRight, Hash } from 'lucide-react';
import * as XLSX from 'xlsx';

interface SidebarProps {
  allData: FinancialRecord[];
  onFilterChange: (filters: any) => void;
  onDataUpload: (data: any[]) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ allData, onFilterChange, onDataUpload }) => {
  const [year, setYear] = useState('all');
  const [client, setClient] = useState('all');
  const [classification, setClassification] = useState('all');
  const [selectedMonths, setSelectedMonths] = useState<string[]>([]);

  const years = Array.from(new Set(allData.map(d => d.año))).sort((a, b) => b - a);
  const clients = Array.from(new Set(allData.map(d => d['nombre cliente']))).sort();
  const classifications = Array.from(new Set(allData.map(d => d.clasificacion))).filter(Boolean).sort();

  useEffect(() => {
    onFilterChange({ year, client, classification, months: selectedMonths });
  }, [year, client, classification, selectedMonths]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const bstr = event.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json(ws);
      onDataUpload(data);
    };
    reader.readAsBinaryString(file);
  };

  const toggleMonth = (m: string) => {
    setSelectedMonths(prev => 
      prev.includes(m) ? prev.filter(x => x !== m) : [...prev, m]
    );
  };

  const resetFilters = () => {
    setYear('all');
    setClient('all');
    setClassification('all');
    setSelectedMonths([]);
  };

  return (
    <aside className="w-80 bg-white border-r border-slate-200 flex flex-col h-full shadow-xl z-20 overflow-hidden">
      <div className="p-6 space-y-8 flex-1 overflow-y-auto no-scrollbar">
        {/* Logo/Title Section */}
        <div className="space-y-1">
          <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Configuration</h2>
          <div className="flex items-center gap-2 text-slate-800">
            <Filter size={20} className="text-blue-600" />
            <span className="font-bold text-lg">Filters & Data</span>
          </div>
        </div>

        {/* Upload Section */}
        <div className="space-y-3">
          <label className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2">
            <Upload size={14} /> Import Dataset
          </label>
          <div className="relative group">
            <input 
              type="file" 
              accept=".xlsx,.xls,.csv" 
              onChange={handleFileUpload}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
            />
            <div className="border-2 border-dashed border-slate-200 group-hover:border-blue-400 group-hover:bg-blue-50 transition-all rounded-xl p-4 text-center">
              <span className="text-xs font-semibold text-slate-500 group-hover:text-blue-600 transition-colors">
                Drop Excel File or Click
              </span>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="space-y-6">
          <div className="space-y-2">
            <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Global Year</label>
            <select 
              value={year} 
              onChange={(e) => setYear(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            >
              <option value="all">All Available Years</option>
              {years.map(y => <option key={y} value={y}>{y}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Client Selection</label>
            <select 
              value={client} 
              onChange={(e) => setClient(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            >
              <option value="all">Consolidated (All Clients)</option>
              {clients.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Classification</label>
            <select 
              value={classification} 
              onChange={(e) => setClassification(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            >
              <option value="all">All Categories</option>
              {classifications.map(c => <option key={c} value={c}>Class {c}</option>)}
            </select>
          </div>

          <div className="space-y-3">
            <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Active Months</label>
            <div className="grid grid-cols-3 gap-1">
              {MONTHS.map(m => (
                <button
                  key={m}
                  onClick={() => toggleMonth(m)}
                  className={`py-2 px-1 text-[10px] font-bold rounded-md border transition-all ${
                    selectedMonths.includes(m)
                      ? 'bg-blue-600 text-white border-blue-600 shadow-md'
                      : 'bg-white text-slate-500 border-slate-100 hover:border-slate-300'
                  }`}
                >
                  {m.substring(0, 3)}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="p-6 border-t border-slate-100 bg-slate-50">
        <button 
          onClick={resetFilters}
          className="w-full flex items-center justify-center gap-2 bg-slate-800 text-white p-3 rounded-xl font-bold text-sm hover:bg-slate-900 transition-all shadow-lg active:scale-95"
        >
          <RotateCcw size={16} />
          Reset Defaults
        </button>
      </div>
    </aside>
  );
};

import React from 'react';
import { FinancialRecord } from '../types';
import { Weight, DollarSign, TrendingUp, FlaskConical, Target, PieChart } from 'lucide-react';

interface KPIsProps {
  data: FinancialRecord[];
}

export const KPIs: React.FC<KPIsProps> = ({ data }) => {
  const sum = (key: keyof FinancialRecord) => data.reduce((acc, curr) => acc + (Number(curr[key]) || 0), 0);

  const totalTons = sum('TON');
  const totalGM = sum('GM');
  const totalGP = sum('GP');
  const totalInv = sum('totalInversion');

  // Calculating Real Ratio (only for clients with investment > 0)
  const activeInvestmentRecords = data.filter(d => (d.totalInversion || 0) > 0);
  const activeGP = activeInvestmentRecords.reduce((acc, curr) => acc + curr.GP, 0);
  const activeInv = activeInvestmentRecords.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0);

  const realRatio = activeGP > 0 ? (activeInv / activeGP) : 0;
  const globalRatio = totalGP > 0 ? (totalInv / totalGP) : 0;

  const formatMillions = (val: number) => {
    if (val >= 1000000) return `$${(val / 1000000).toFixed(1)}M`;
    return `$${val.toLocaleString()}`;
  };

  const kpiList = [
    { label: 'Metric Tons', value: totalTons.toLocaleString(), sub: 'Volume (TON)', icon: Weight, color: 'bg-amber-500' },
    { label: 'Gross Margin', value: formatMillions(totalGM), sub: 'Profitability (GM)', icon: DollarSign, color: 'bg-emerald-500' },
    { label: 'Gross Profit', value: formatMillions(totalGP), sub: 'Gross Profit (GP)', icon: TrendingUp, color: 'bg-blue-600' },
    { label: 'Lab Investment', value: formatMillions(totalInv), sub: 'Total Assets (INV)', icon: FlaskConical, color: 'bg-violet-600' },
    { label: 'Global Index', value: (globalRatio * 10).toFixed(2), sub: 'Target < 0.8', icon: PieChart, color: globalRatio > 0.08 ? 'bg-rose-500' : 'bg-pink-600' },
    { label: 'Real Index', value: (realRatio * 10).toFixed(2), sub: 'Active Accounts', icon: Target, color: 'bg-teal-600' },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6">
      {kpiList.map((kpi, idx) => (
        <div key={idx} className={`${kpi.color} p-5 rounded-2xl shadow-xl shadow-slate-200/50 text-white flex flex-col justify-between transform hover:-translate-y-1 transition-all duration-300`}>
          <div className="flex justify-between items-start mb-4">
            <div className="p-2 bg-white/20 rounded-xl">
              <kpi.icon size={20} />
            </div>
            <span className="text-[10px] font-bold uppercase tracking-widest opacity-70">
              {kpi.sub}
            </span>
          </div>
          <div>
            <p className="text-3xl font-extrabold tracking-tight">{kpi.value}</p>
            <h3 className="text-xs font-semibold mt-1 opacity-90">{kpi.label}</h3>
          </div>
        </div>
      ))}
    </div>
  );
};

