        month: m.substring(0, 3),
        gp: filtered.reduce((acc, curr) => acc + curr.GP, 0),
        investment: filtered.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0),
        tons: filtered.reduce((acc, curr) => acc + curr.TON, 0),
