import { FinancialRecord } from '../types';

export const MONTHS = [
  'ENERO', 'FEBRERO', 'MARZO', 'ABRIL', 'MAYO', 'JUNIO', 
  'JULIO', 'AGOSTO', 'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'
];

function excelDateToJSDate(serial: number) {
  return new Date(Math.round((serial - 25569) * 86400 * 1000));
}

export const processRawData = (data: any[]): FinancialRecord[] => {
  return data.map(row => {
    const findKey = (r: any, search: string) => {
      const key = Object.keys(r).find(k => k.toLowerCase() === search.toLowerCase());
      return key ? r[key] : undefined;
    };

    const parseNum = (val: any) => {
      if (typeof val === 'number') return val;
      if (!val) return 0;
      return parseFloat(String(val).replace(/[^0-9.-]+/g, "")) || 0;
    };

    const año = parseNum(findKey(row, 'año'));
    let rawFecha = findKey(row, 'Fecha');
    let dateObj: Date | null = null;

    if (typeof rawFecha === 'number') {
      dateObj = excelDateToJSDate(rawFecha);
    } else if (typeof rawFecha === 'string') {
      const idx = MONTHS.indexOf(rawFecha.trim().toUpperCase());
      if (idx !== -1) {
        dateObj = new Date(año || new Date().getFullYear(), idx, 1);
      } else {
        dateObj = new Date(rawFecha);
      }
    }

    if (!dateObj || isNaN(dateObj.getTime())) return null;

    const gp = parseNum(findKey(row, 'GP'));
    const labInv = parseNum(findKey(row, 'inversion analisis lab'));
    const nirInv = parseNum(findKey(row, 'Inversion Nir'));
    const micoInv = parseNum(findKey(row, 'Inversion equipos Micotoxinas'));
    const totalInv = labInv + nirInv + micoInv;

    // Explicitly typing the returned object as FinancialRecord to fix type predicate issues in filter
    const record: FinancialRecord = {
      Fecha: MONTHS[dateObj.getMonth()],
      año: dateObj.getFullYear(),
      clasificacion: String(findKey(row, 'clasificacion') || 'N/A').toUpperCase().trim(),
      'nombre cliente': String(findKey(row, 'nombre cliente') || 'Unknown').trim(),
      TON: parseNum(findKey(row, 'TON')),
      'TURN OVER': parseNum(findKey(row, 'TURN OVER')),
      GM: parseNum(findKey(row, 'GM')),
      GP: gp,
      'inversion analisis lab': labInv,
      'Inversion Nir': nirInv,
      'Inversion equipos Micotoxinas': micoInv,
      totalInversion: totalInv,
      '% Inversion Lab': gp > 0 ? (totalInv / gp) : 0,
      date: dateObj
    };
    return record;
  }).filter((r): r is FinancialRecord => r !== null);
};

