          <div className="bg-rose-100 p-2 rounded-lg text-rose-600">
            <AlertCircle size={20} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-800">High Investment Ratio Accounts</h3>
            <p className="text-xs text-slate-500 font-medium">Clients exceeding the 8.0% recommended threshold</p>
          </div>
        </div>
        <span className="bg-rose-50 text-rose-700 px-3 py-1 rounded-full text-xs font-bold border border-rose-100">
          {highRisk.length} Flagged
        </span>
      </div>

      <div className="flex-1 overflow-auto max-h-[400px]">
        <table className="w-full text-left border-collapse">
          <thead className="sticky top-0 bg-white shadow-sm z-10">
            <tr>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50">Account Name</th>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50">Gross Profit (GP)</th>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50">Inv. Lab</th>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50">Ratio</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {highRisk.length > 0 ? (
              highRisk.map((client, idx) => (
                <tr key={idx} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4 text-sm font-bold text-slate-700 group-hover:text-blue-600">{client.name}</td>
                  <td className="px-6 py-4 text-sm font-medium text-slate-600">${Math.round(client.gp).toLocaleString()}</td>
                  <td className="px-6 py-4 text-sm font-medium text-slate-600">${Math.round(client.inv).toLocaleString()}</td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-bold text-rose-600">{client.ratio.toFixed(2)}%</span>
                      <TrendingUp size={14} className="text-rose-400" />
                    </div>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={4} className="px-6 py-12 text-center text-slate-400 text-sm font-medium italic">
                  Excellent health. No accounts currently exceed the 8% investment threshold.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

