import React from 'react';
import { FinancialRecord } from '../types';
import { Weight, DollarSign, TrendingUp, FlaskConical, Target } from 'lucide-react';

interface KPIsProps {
  data: FinancialRecord[];
}

export const KPIs: React.FC<KPIsProps> = ({ data }) => {
  const sum = (key: keyof FinancialRecord) => data.reduce((acc, curr) => acc + (Number(curr[key]) || 0), 0);

  const totalTons = sum('TON');
  const totalGM = sum('GM');
  const totalGP = sum('GP');
  const totalInv = sum('totalInversion');

  // Calculating Real Ratio (only for clients with investment > 0)
  const activeInvestmentRecords = data.filter(d => (d.totalInversion || 0) > 0);
  const activeGP = activeInvestmentRecords.reduce((acc, curr) => acc + curr.GP, 0);
  const activeInv = activeInvestmentRecords.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0);

  const realRatio = activeGP > 0 ? (activeInv / activeGP) : 0;

  /**
   * Formateador: Muestra valores en miles para mejor lectura
   */
  const formatInThousands = (val: number) => {
    return `$${Math.round(val / 1000).toLocaleString()}k`;
  };

  /**
   * Cálculo de Real Index: Alta precisión (4 decimales)
   */
  const realIndexValue = ((realRatio * 10) / 100).toFixed(4);

  const kpiList = [
    { label: 'Metric Tons', value: Math.round(totalTons / 1000).toLocaleString(), sub: 'Volume (TON x1000)', icon: Weight, color: 'bg-amber-500' },
    { label: 'Gross Margin', value: formatInThousands(totalGM), sub: 'Profitability (GM)', icon: DollarSign, color: 'bg-emerald-500' },
    { label: 'Gross Profit', value: formatInThousands(totalGP), sub: 'Gross Profit (GP)', icon: TrendingUp, color: 'bg-blue-600' },
    { label: 'Lab Investment', value: formatInThousands(totalInv), sub: 'Total Assets (INV)', icon: FlaskConical, color: 'bg-violet-600' },
    { label: 'Real Index', value: realIndexValue, sub: 'Efficiency Score', icon: Target, color: 'bg-teal-600' },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
      {kpiList.map((kpi, idx) => (
        <div key={idx} className={`${kpi.color} p-5 rounded-2xl shadow-xl shadow-slate-200/50 text-white flex flex-col justify-between transform hover:-translate-y-1 transition-all duration-300`}>
          <div className="flex justify-between items-start mb-4">
            <div className="p-2 bg-white/20 rounded-xl">
              <kpi.icon size={20} />
            </div>
            <span className="text-[10px] font-bold uppercase tracking-widest opacity-70">
              {kpi.sub}
            </span>
          </div>
          <div>
