export const Charts: React.FC<ChartsProps> = ({ data }) => {
  // 1. Trend Data for Monthly Charts
  const trendData = useMemo(() => {
    const grouped = MONTHS.map(m => {
      const filtered = data.filter(d => d.Fecha.toUpperCase() === m);
      return {
        month: m.substring(0, 3),
        gp: filtered.reduce((acc, curr) => acc + curr.GP, 0),
        labInv: filtered.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0),
      };
    }).filter(d => d.gp > 0 || d.labInv > 0);
    return grouped;
  }, [data]);

  // 2. Investment Distribution for Donut Chart
  const distributionData = useMemo(() => {
    const lab = data.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0);
    const nir = data.reduce((acc, curr) => acc + curr['Inversion Nir'], 0);
    const mico = data.reduce((acc, curr) => acc + curr['Inversion equipos Micotoxinas'], 0);
    return [
      { name: 'Analysis Lab', value: lab, color: '#3b82f6' },
      { name: 'NIR', value: nir, color: '#10b981' },
      { name: 'Mycotoxins', value: mico, color: '#f59e0b' }
    ];
  }, [data]);

  // 3. High Risk Ratio (>8%) Bar Chart Data - Synchronized with DataTable (Ratio / 1000)
  const highRiskData = useMemo(() => {
    const clientGroups = data.reduce((acc, curr) => {
      const name = curr['nombre cliente'];
      if (!acc[name]) acc[name] = { gp: 0, inv: 0 };
      acc[name].gp += curr.GP;
      acc[name].inv += (curr.totalInversion || 0);
      return acc;
    }, {} as Record<string, { gp: number; inv: number }>);

    return Object.keys(clientGroups)
      .map(name => {
        const group = clientGroups[name];
        const rawRatio = group.gp > 0 ? (group.inv / group.gp) * 100 : 0;
        // Apply the same division as requested for the table display
        const displayRatio = rawRatio / 1000;
        return { name, ratio: displayRatio, rawRatio };
      })
      .filter(item => item.rawRatio > 8)
      .sort((a, b) => b.rawRatio - a.rawRatio)
      .slice(0, 10); 
  }, [data]);

  // 4. Average Investment by Classification
  const classificationData = useMemo(() => {
    const groups: Record<string, { total: number; count: number }> = {};
    data.forEach(item => {
      const cls = item.clasificacion || 'N/A';
