      groups[cls].total += (item.totalInversion || 0);
      groups[cls].count += 1;
    });
    return Object.entries(groups).map(([name, stats]) => ({
      name: `Class ${name}`,
      avg: stats.count > 0 ? stats.total / stats.count : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
