                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "GP"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Area type="monotone" dataKey="gp" stroke="#2563eb" strokeWidth={2.5} fillOpacity={1} fill="url(#colorGp)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
