import React, { useState, useEffect } from 'react';
import { FinancialRecord } from '../types';
import { MONTHS } from '../utils/dataProcessor';
import { Filter, Upload, RotateCcw, Calendar, CheckSquare, Square } from 'lucide-react';
import * as XLSX from 'xlsx';

interface SidebarProps {
  allData: FinancialRecord[];
  onFilterChange: (filters: any) => void;
  onDataUpload: (data: any[]) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ allData, onFilterChange, onDataUpload }) => {
  const [year, setYear] = useState('all');
  const [client, setClient] = useState('all');
  const [classification, setClassification] = useState('all');
  const [selectedMonths, setSelectedMonths] = useState<string[]>([]);

  const years = Array.from(new Set(allData.map(d => d.año))).sort((a: number, b: number) => b - a);
  const clients = Array.from(new Set(allData.map(d => d['nombre cliente']))).sort();
  const classifications = Array.from(new Set(allData.map(d => d.clasificacion))).filter(Boolean).sort();

  useEffect(() => {
    onFilterChange({ 
      year, 
      client, 
      classification, 
      months: selectedMonths 
    });
  }, [year, client, classification, selectedMonths]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const bstr = event.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json(ws);
      onDataUpload(data);
    };
    reader.readAsBinaryString(file);
  };

  const toggleMonth = (m: string) => {
    setSelectedMonths(prev => 
      prev.includes(m) ? prev.filter(month => month !== m) : [...prev, m]
    );
  };

  const toggleAllMonths = () => {
    if (selectedMonths.length === MONTHS.length) {
      setSelectedMonths([]);
    } else {
      setSelectedMonths([...MONTHS]);
    }
  };

  const resetFilters = () => {
    setYear('all');
    setClient('all');
    setClassification('all');
    setSelectedMonths([]);
  };

  return (
    <aside className="w-80 bg-white border-r border-slate-200 flex flex-col h-full shadow-xl z-20 overflow-hidden">
      <div className="p-6 space-y-8 flex-1 overflow-y-auto no-scrollbar">
        {/* Logo/Title Section */}
        <div className="space-y-1">
          <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Configuration</h2>
          <div className="flex items-center gap-2 text-slate-800">
            <Filter size={20} className="text-blue-600" />
            <span className="font-bold text-lg">Filters & Data</span>
          </div>
        </div>

        {/* Upload Section */}
        <div className="space-y-3">
          <label className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2">
            <Upload size={14} /> Import Dataset
          </label>
          <div className="relative group">
            <input 
              type="file" 
              accept=".xlsx,.xls,.csv" 
              onChange={handleFileUpload}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
            />
            <div className="border-2 border-dashed border-slate-200 group-hover:border-blue-400 group-hover:bg-blue-50 transition-all rounded-xl p-4 text-center">
              <span className="text-xs font-semibold text-slate-500 group-hover:text-blue-600 transition-colors">
                Drop Excel File or Click
              </span>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="space-y-6">
          {/* Year Filter */}
          <div className="space-y-2">
            <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Global Year</label>
            <select 
              value={year} 
              onChange={(e) => setYear(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            >
              <option value="all">All Available Years</option>
              {years.map(y => <option key={y} value={y}>{y}</option>)}
            </select>
          </div>

          {/* Multi-Month Grid Filter */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest flex items-center gap-1">
