import React, { useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell, PieChart, Pie, LabelList
} from 'recharts';
import { FinancialRecord } from '../types';
import { MONTHS } from '../utils/dataProcessor';

interface ChartsProps {data: FinancialRecord[];}

export const Charts: React.FC<ChartsProps> = ({ data }) => {
  // 1. Trend Data for Monthly Charts
  const trendData = useMemo(() => {
    const grouped = MONTHS.map(m => {
      const filtered = data.filter(d => d.Fecha.toUpperCase() === m);
      return {
        month: m.substring(0, 3),
        gp: filtered.reduce((acc, curr) => acc + curr.GP, 0),
        labInv: filtered.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0),
      };
    }).filter(d => d.gp > 0 || d.labInv > 0);
    return grouped;
  }, [data]);

  // 2. Investment Distribution for Donut Chart
  const distributionData = useMemo(() => {
    const lab = data.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0);
    const nir = data.reduce((acc, curr) => acc + curr['Inversion Nir'], 0);
    const mico = data.reduce((acc, curr) => acc + curr['Inversion equipos Micotoxinas'], 0);
    return [
      { name: 'Analysis Lab', value: lab, color: '#3b82f6' },
      { name: 'NIR', value: nir, color: '#10b981' },
      { name: 'Mycotoxins', value: mico, color: '#f59e0b' }
    ];
  }, [data]);

  // 3. High Risk Ratio (>8%) Bar Chart Data - Synchronized with DataTable (Ratio / 1000)
  const highRiskData = useMemo(() => {
    const clientGroups = data.reduce((acc, curr) => {
      const name = curr['nombre cliente'];
      if (!acc[name]) acc[name] = { gp: 0, inv: 0 };
      acc[name].gp += curr.GP;
      acc[name].inv += (curr.totalInversion || 0);
      return acc;
    }, {} as Record<string, { gp: number; inv: number }>);

    return Object.keys(clientGroups)
      .map(name => {
        const group = clientGroups[name];
        const rawRatio = group.gp > 0 ? (group.inv / group.gp) * 100 : 0;
        // Apply the same division as requested for the table display
        const displayRatio = rawRatio / 1000;
        return { name, ratio: displayRatio, rawRatio };
      })
      .filter(item => item.rawRatio > 8)
      .sort((a, b) => b.rawRatio - a.rawRatio)
      .slice(0, 10); 
  }, [data]);

  // 4. Average Investment by Classification
  const classificationData = useMemo(() => {
    const groups: Record<string, { total: number; count: number }> = {};
    data.forEach(item => {
      const cls = item.clasificacion || 'N/A';
      if (!groups[cls]) groups[cls] = { total: 0, count: 0 };
      groups[cls].total += (item.totalInversion || 0);
      groups[cls].count += 1;
    });
    return Object.entries(groups).map(([name, stats]) => ({
      name: `Class ${name}`,
      avg: stats.count > 0 ? stats.total / stats.count : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
  }, [data]);

  const formatCurrency = (value: number) => `$${Math.round(value).toLocaleString()}`;
  const formatPercent = (value: number) => `${value.toFixed(2)}%`;

  return (
    <div className="space-y-8">
      {/* Row 1: Main Trends (50/50 split) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* GP Trend */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-blue-600 rounded-full"></span>
            Monthly Gross Profit Trend
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorGp" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "GP"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Area type="monotone" dataKey="gp" stroke="#2563eb" strokeWidth={2.5} fillOpacity={1} fill="url(#colorGp)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Lab Investment Trend */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-violet-500 rounded-full"></span>
            Lab Investment Trend
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={trendData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "Lab Inv"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="labInv" fill="#8b5cf6" radius={[6, 6, 0, 0]} barSize={32} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Row 2: Risk Profile (Full Width) - Synchronized values with DataTable */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
        <div className="flex items-center justify-between mb-6">
          <h3 className="text-sm font-bold text-slate-800 flex items-center gap-2">
            <span className="w-2 h-2 bg-rose-500 rounded-full animate-pulse"></span>
            Critical Investment Ratios per Client (Synced Display)
          </h3>
          <div className="flex flex-col items-end">
             <span className="text-[10px] font-bold text-rose-600 bg-rose-50 px-3 py-1 rounded-full border border-rose-100 uppercase mb-1">
              {highRiskData.length} Flagged Accounts
            </span>
            <span className="text-[9px] text-slate-400 font-bold uppercase tracking-wider">Ratio = (Inv/GP)*100 / 1000</span>
          </div>
        </div>
        <div className="flex-1 w-full">
          {highRiskData.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={highRiskData} layout="vertical" margin={{ left: 40, right: 30 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                <XAxis type="number" hide domain={[0, 'auto']} />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={140} 
                  tick={{fontSize: 10, fill: '#64748b', fontWeight: 600}} 
                  axisLine={false} 
                  tickLine={false} 
                />
                <Tooltip 
                  formatter={(value: number) => [formatPercent(value), "Ratio Display"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="ratio" radius={[0, 6, 6, 0]} barSize={22}>
                   <LabelList dataKey="ratio" position="right" formatter={(v: number) => `${v.toFixed(2)}%`} style={{ fontSize: '10px', fill: '#f43f5e', fontWeight: 'bold' }} />
                  {highRiskData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill="#f43f5e" />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 text-xs italic space-y-2">
              <p>✅ All accounts within healthy thresholds.</p>
            </div>
          )}
        </div>
      </div>

      {/* Row 3: Allocation and Avg Inv (50/50 split) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Asset Allocation */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-emerald-500 rounded-full"></span>
            Asset Allocation
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={distributionData}
                  cx="50%"
                  cy="45%"
                  innerRadius={65}
                  outerRadius={85}
                  paddingAngle={8}
                  dataKey="value"
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                  labelLine={{ stroke: '#cbd5e1', strokeWidth: 1 }}
                >
                  {distributionData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip formatter={(value: number) => formatCurrency(value)} />
                <Legend verticalAlign="bottom" align="center" iconType="circle" wrapperStyle={{ paddingTop: '20px', fontSize: '11px', color: '#64748b' }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Avg Investment by Classification */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-indigo-500 rounded-full"></span>
            Avg Investment by Classification
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={classificationData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 11, fill: '#64748b', fontWeight: 600}} />
                <YAxis hide />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "Avg Investment"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="avg" fill="#6366f1" radius={[8, 8, 0, 0]} barSize={40}>
                  <LabelList 
                    dataKey="avg" 
                    position="top" 
                    formatter={(v: number) => `$${Math.round(v/1000)}k`}
                    style={{ fontSize: '10px', fontWeight: 'bold', fill: '#6366f1' }}
                  />
                  {classificationData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#6366f1' : '#818cf8'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { KPIs } from './components/KPIs';
import { Charts } from './components/Charts';
import { DataTable } from './components/DataTable';
import { FinancialRecord } from './types';
import { processRawData, getBackupData } from './utils/dataProcessor';
import { LayoutDashboard } from 'lucide-react';

const App: React.FC = () => {
  const [allData, setAllData] = useState<FinancialRecord[]>([]);
  const [filteredData, setFilteredData] = useState<FinancialRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Initialize with backup data
  useEffect(() => {
    const data = processRawData(getBackupData());
    setAllData(data);
    setFilteredData(data);
    setIsLoading(false);
  }, []);

  const handleDataUpdate = (newData: any[]) => {
    setIsLoading(true);
    const processed = processRawData(newData);
    setAllData(processed);
    setFilteredData(processed);
    setIsLoading(false);
  };

  const handleFilterChange = (filters: {
    year: string;
    client: string;
    classification: string;
    months: string[];
  }) => {
    const filtered = allData.filter((item) => {
      const yearMatch = filters.year === 'all' || item.año.toString() === filters.year;
      const clientMatch = filters.client === 'all' || item['nombre cliente'] === filters.client;
      const classMatch = filters.classification === 'all' || item.clasificacion === filters.classification;
      const monthMatch = filters.months.length === 0 || filters.months.includes(item.Fecha.toUpperCase());
      return yearMatch && clientMatch && classMatch && monthMatch;
    });
    setFilteredData(filtered);
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden text-slate-900">
