import React, { useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell, PieChart, Pie, LabelList
} from 'recharts';
import { FinancialRecord } from '../types';
import { MONTHS } from '../utils/dataProcessor';

interface ChartsProps {data: FinancialRecord[];}

export const Charts: React.FC<ChartsProps> = ({ data }) => {
  // 1. Trend Data for Monthly Charts
  const trendData = useMemo(() => {
    const grouped = MONTHS.map(m => {
      const filtered = data.filter(d => d.Fecha.toUpperCase() === m);
      return {
        month: m.substring(0, 3),
        gp: filtered.reduce((acc, curr) => acc + curr.GP, 0),
        labInv: filtered.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0),
      };
    }).filter(d => d.gp > 0 || d.labInv > 0);
    return grouped;
  }, [data]);

  // 2. Investment Distribution for Donut Chart
  const distributionData = useMemo(() => {
    const lab = data.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0);
    const nir = data.reduce((acc, curr) => acc + curr['Inversion Nir'], 0);
    const mico = data.reduce((acc, curr) => acc + curr['Inversion equipos Micotoxinas'], 0);
    return [
      { name: 'Analysis Lab', value: lab, color: '#3b82f6' },
      { name: 'NIR', value: nir, color: '#10b981' },
      { name: 'Mycotoxins', value: mico, color: '#f59e0b' }
    ];
  }, [data]);

  // 3. High Risk Ratio (>8%) Bar Chart Data - Synchronized with DataTable (Ratio / 1000)
  const highRiskData = useMemo(() => {
    const clientGroups = data.reduce((acc, curr) => {
      const name = curr['nombre cliente'];
      if (!acc[name]) acc[name] = { gp: 0, inv: 0 };
      acc[name].gp += curr.GP;
      acc[name].inv += (curr.totalInversion || 0);
      return acc;
    }, {} as Record<string, { gp: number; inv: number }>);

    return Object.keys(clientGroups)
      .map(name => {
        const group = clientGroups[name];
        const rawRatio = group.gp > 0 ? (group.inv / group.gp) * 100 : 0;
        // Apply the same division as requested for the table display
        const displayRatio = rawRatio / 1000;
        return { name, ratio: displayRatio, rawRatio };
      })
      .filter(item => item.rawRatio > 8)
      .sort((a, b) => b.rawRatio - a.rawRatio)
      .slice(0, 10); 
  }, [data]);

  // 4. Average Investment by Classification
  const classificationData = useMemo(() => {
    const groups: Record<string, { total: number; count: number }> = {};
    data.forEach(item => {
      const cls = item.clasificacion || 'N/A';
      if (!groups[cls]) groups[cls] = { total: 0, count: 0 };
      groups[cls].total += (item.totalInversion || 0);
      groups[cls].count += 1;
    });
    return Object.entries(groups).map(([name, stats]) => ({
      name: `Class ${name}`,
      avg: stats.count > 0 ? stats.total / stats.count : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
  }, [data]);

  const formatCurrency = (value: number) => `$${Math.round(value).toLocaleString()}`;
  const formatPercent = (value: number) => `${value.toFixed(2)}%`;

  return (
    <div className="space-y-8">
      {/* Row 1: Main Trends (50/50 split) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* GP Trend */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-blue-600 rounded-full"></span>
            Monthly Gross Profit Trend
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorGp" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "GP"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Area type="monotone" dataKey="gp" stroke="#2563eb" strokeWidth={2.5} fillOpacity={1} fill="url(#colorGp)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Lab Investment Trend */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-violet-500 rounded-full"></span>
            Lab Investment Trend
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={trendData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "Lab Inv"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="labInv" fill="#8b5cf6" radius={[6, 6, 0, 0]} barSize={32} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Row 2: Allocation and Avg Inv (50/50 split) - SUBIDA */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Asset Allocation (Donut) */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-emerald-500 rounded-full"></span>
            Asset Allocation
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={distributionData}
                  cx="50%"
                  cy="45%"
                  innerRadius={65}
                  outerRadius={85}
                  paddingAngle={8}
                  dataKey="value"
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                  labelLine={{ stroke: '#cbd5e1', strokeWidth: 1 }}
                >
                  {distributionData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip formatter={(value: number) => formatCurrency(value)} />
                <Legend verticalAlign="bottom" align="center" iconType="circle" wrapperStyle={{ paddingTop: '20px', fontSize: '11px', color: '#64748b' }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Avg Investment by Classification */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-indigo-500 rounded-full"></span>
            Avg Investment by Classification
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={classificationData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 11, fill: '#64748b', fontWeight: 600}} />
                <YAxis hide />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "Avg Investment"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="avg" fill="#6366f1" radius={[8, 8, 0, 0]} barSize={40}>
                  <LabelList 
                    dataKey="avg" 
                    position="top" 
                    formatter={(v: number) => `$${Math.round(v/1000)}k`}
                    style={{ fontSize: '10px', fontWeight: 'bold', fill: '#6366f1' }}
                  />
                  {classificationData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#6366f1' : '#818cf8'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Row 3: Risk Profile (Full Width) - BAJADA */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
        <div className="flex items-center justify-between mb-6">
          <h3 className="text-sm font-bold text-slate-800 flex items-center gap-2">
            <span className="w-2 h-2 bg-rose-500 rounded-full animate-pulse"></span>
            Critical Investment Ratios per Client (Synced Display)
          </h3>
          <div className="flex flex-col items-end">
             <span className="text-[10px] font-bold text-rose-600 bg-rose-50 px-3 py-1 rounded-full border border-rose-100 uppercase mb-1">
              {highRiskData.length} Flagged Accounts
            </span>
            <span className="text-[9px] text-slate-400 font-bold uppercase tracking-wider">Ratio = (Inv/GP)*100 / 1000</span>
          </div>
        </div>
        <div className="flex-1 w-full">
          {highRiskData.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={highRiskData} layout="vertical" margin={{ left: 40, right: 30 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                <XAxis type="number" hide domain={[0, 'auto']} />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={140} 
                  tick={{fontSize: 10, fill: '#64748b', fontWeight: 600}} 
                  axisLine={false} 
                  tickLine={false} 
                />
                <Tooltip 
                  formatter={(value: number) => [formatPercent(value), "Ratio Display"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="ratio" radius={[0, 6, 6, 0]} barSize={22}>
                   <LabelList dataKey="ratio" position="right" formatter={(v: number) => `${v.toFixed(2)}%`} style={{ fontSize: '10px', fill: '#f43f5e', fontWeight: 'bold' }} />
                  {highRiskData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill="#f43f5e" />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 text-xs italic space-y-2">
              <p>✅ All accounts within healthy thresholds.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { KPIs } from './components/KPIs';
import { Charts } from './components/Charts';
import { DataTable } from './components/DataTable';
import { FinancialRecord } from './types';
import { processRawData, getBackupData } from './utils/dataProcessor';
import { LayoutDashboard, Menu, X } from 'lucide-react';

const App: React.FC = () => {
  const [allData, setAllData] = useState<FinancialRecord[]>([]);
  const [filteredData, setFilteredData] = useState<FinancialRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // Initialize with backup data
  useEffect(() => {
    const data = processRawData(getBackupData());
    setAllData(data);
    setFilteredData(data);
    setIsLoading(false);
  }, []);

  const handleDataUpdate = (newData: any[]) => {
    setIsLoading(true);
    const processed = processRawData(newData);
    setAllData(processed);
    setFilteredData(processed);
    setIsLoading(false);
  };

  const handleFilterChange = (filters: {
    year: string;
    client: string;
    classification: string;
    months: string[];
  }) => {
    const filtered = allData.filter((item) => {
      const yearMatch = filters.year === 'all' || item.año.toString() === filters.year;
      const clientMatch = filters.client === 'all' || item['nombre cliente'] === filters.client;
      const classMatch = filters.classification === 'all' || item.clasificacion === filters.classification;
      const monthMatch = filters.months.length === 0 || filters.months.includes(item.Fecha.toUpperCase());
      return yearMatch && clientMatch && classMatch && monthMatch;
    });
    setFilteredData(filtered);
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden text-slate-900">
      {/* Sidebar con transiciones */}
      <div className={`fixed inset-y-0 left-0 z-30 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 transition-all duration-300 ease-in-out`}>
        <Sidebar 
          allData={allData} 
          onFilterChange={handleFilterChange} 
          onDataUpload={handleDataUpdate}
          onClose={() => setIsSidebarOpen(false)}
          isOpen={isSidebarOpen}
        />
      </div>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden w-full">
        {/* Header */}
        <header className="bg-white border-b border-slate-200 px-8 py-4 flex items-center justify-between shadow-sm z-10">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-100 rounded-lg transition-colors text-slate-600 lg:hidden"
            >
              <Menu size={24} />
            </button>
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-100 rounded-lg transition-colors text-slate-600 hidden lg:block"
            >
              {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-lg">
                <LayoutDashboard className="text-white w-6 h-6" />
              </div>
              <div>
                <h1 className="text-xl font-bold text-slate-800">Inteligencia Financiera</h1>
                <p className="text-xs text-slate-500 font-medium">Panel de Rendimiento Empresarial</p>
              </div>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-4">
            <div className="text-right">
              <span className="text-xs text-slate-400 block uppercase tracking-wider font-bold">Estado de Datos</span>
              <span className="text-sm font-semibold text-emerald-600 flex items-center gap-1">
                <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                Dataset Activo
              </span>
            </div>
          </div>
        </header>

        {/* Dashboard Scrollable Area */}
        <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
          {isLoading ? (
            <div className="flex items-center justify-center h-full">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
          ) : (
            <>
              {/* Top Row: KPIs */}
              <KPIs data={filteredData} />

              {/* Middle Row: Trend Charts */}
              <Charts data={filteredData} />

              {/* Bottom Row: Detailed Table */}
              <div className="w-full">
                <DataTable data={filteredData} />
              </div>
            </>
          )}
        </div>
      </main>

      {/* Overlay para móviles cuando el sidebar está abierto */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/20 z-20 lg:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { FinancialRecord } from '../types';
import { MONTHS } from '../utils/dataProcessor';
import { Filter, Upload, RotateCcw, Calendar, ChevronLeft } from 'lucide-react';
import * as XLSX from 'xlsx';

interface SidebarProps {
  allData: FinancialRecord[];
  onFilterChange: (filters: any) => void;
  onDataUpload: (data: any[]) => void;
  onClose?: () => void;
  isOpen?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({ allData, onFilterChange, onDataUpload, onClose, isOpen }) => {
  const [year, setYear] = useState('all');
  const [client, setClient] = useState('all');
  const [classification, setClassification] = useState('all');
  const [selectedMonths, setSelectedMonths] = useState<string[]>([]);

  const years = Array.from(new Set(allData.map(d => d.año))).sort((a: number, b: number) => b - a);
  const clients = Array.from(new Set(allData.map(d => d['nombre cliente']))).sort();
  const classifications = Array.from(new Set(allData.map(d => d.clasificacion))).filter(Boolean).sort();

  useEffect(() => {
    onFilterChange({ 
      year, 
      client, 
      classification, 
      months: selectedMonths 
    });
  }, [year, client, classification, selectedMonths]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const bstr = event.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json(ws);
      onDataUpload(data);
    };
    reader.readAsBinaryString(file);
  };

  const toggleMonth = (m: string) => {
    setSelectedMonths(prev => 
      prev.includes(m) ? prev.filter(month => month !== m) : [...prev, m]
    );
  };

  const toggleAllMonths = () => {
    if (selectedMonths.length === MONTHS.length) {
      setSelectedMonths([]);
    } else {
      setSelectedMonths([...MONTHS]);
    }
  };

  const resetFilters = () => {
    setYear('all');
    setClient('all');
    setClassification('all');
    setSelectedMonths([]);
  };

  return (
    <aside className={`w-80 bg-white border-r border-slate-200 flex flex-col h-full shadow-xl z-20 overflow-hidden transition-all duration-300`}>
      <div className="p-6 space-y-8 flex-1 overflow-y-auto no-scrollbar">
        {/* Logo/Title Section */}
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Configuración</h2>
            <div className="flex items-center gap-2 text-slate-800">
              <Filter size={20} className="text-blue-600" />
              <span className="font-bold text-lg">Filtros y Datos</span>
            </div>
          </div>
          {onClose && (
            <button 
              onClick={onClose}
              className="p-2 hover:bg-slate-100 rounded-lg text-slate-400 lg:hidden"
            >
              <ChevronLeft size={20} />
            </button>
          )}
        </div>

        {/* Upload Section */}
        <div className="space-y-3">
          <label className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2">
            <Upload size={14} /> Importar Datos
          </label>
          <div className="relative group">
            <input 
              type="file" 
              accept=".xlsx,.xls,.csv" 
              onChange={handleFileUpload}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
            />
            <div className="border-2 border-dashed border-slate-200 group-hover:border-blue-400 group-hover:bg-blue-50 transition-all rounded-xl p-4 text-center">
              <span className="text-xs font-semibold text-slate-500 group-hover:text-blue-600 transition-colors">
                Arrastre archivo Excel o haga clic
              </span>
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="space-y-6">
          {/* Year Filter */}
          <div className="space-y-2">
            <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Año Global</label>
            <select 
              value={year} 
              onChange={(e) => setYear(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            >
              <option value="all">Todos los años</option>
              {years.map(y => <option key={y} value={y}>{y}</option>)}
            </select>
          </div>

          {/* Multi-Month Grid Filter */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest flex items-center gap-1">
                <Calendar size={10} /> Selección de Meses
              </label>
              <button 
                onClick={toggleAllMonths}
                className="text-[9px] font-bold text-blue-600 hover:underline uppercase tracking-tighter"
              >
                {selectedMonths.length === MONTHS.length ? 'Limpiar' : 'Todos'}
              </button>
            </div>
            <div className="grid grid-cols-3 gap-1.5">
              {MONTHS.map(m => {
                const isSelected = selectedMonths.includes(m);
                return (
                  <button
                    key={m}
                    onClick={() => toggleMonth(m)}
                    className={`py-2 px-1 text-[10px] font-bold rounded-md border transition-all truncate ${
                      isSelected 
                        ? 'bg-blue-600 border-blue-600 text-white shadow-md shadow-blue-200' 
                        : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300 hover:bg-slate-50'
                    }`}
                  >
                    {m.substring(0, 3)}
                  </button>
                );
              })}
            </div>
            <p className="text-[9px] text-slate-400 font-medium italic">
              {selectedMonths.length === 0 ? '* Viendo todos los meses' : `* ${selectedMonths.length} seleccionados`}
            </p>
          </div>

          {/* Client Selection */}
          <div className="space-y-2">
            <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Selección de Cliente</label>
            <select 
              value={client} 
              onChange={(e) => setClient(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            >
              <option value="all">Consolidado (Todos)</option>
              {clients.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          {/* Classification Filter */}
          <div className="space-y-2">
            <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Clasificación</label>
            <select 
              value={classification} 
              onChange={(e) => setClassification(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            >
              <option value="all">Todas las categorías</option>
              {classifications.map(c => <option key={c} value={c}>Clase {c}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="p-6 border-t border-slate-100 bg-slate-50">
        <button 
          onClick={resetFilters}
          className="w-full flex items-center justify-center gap-2 bg-slate-800 text-white p-3 rounded-xl font-bold text-sm hover:bg-slate-900 transition-all shadow-lg active:scale-95"
        >
          <RotateCcw size={16} />
          Restablecer Filtros
        </button>
      </div>
    </aside>
  );
};

import React from 'react';
import { FinancialRecord } from '../types';
import { Weight, DollarSign, TrendingUp, FlaskConical, Target } from 'lucide-react';

interface KPIsProps {
  data: FinancialRecord[];
}

export const KPIs: React.FC<KPIsProps> = ({ data }) => {
  const sum = (key: keyof FinancialRecord) => data.reduce((acc, curr) => acc + (Number(curr[key]) || 0), 0);

  const totalTons = sum('TON');
  const totalGM = sum('GM');
  const totalGP = sum('GP');
  const totalInv = sum('totalInversion');

  // Calculating Real Ratio (only for clients with investment > 0)
  const activeInvestmentRecords = data.filter(d => (d.totalInversion || 0) > 0);
  const activeGP = activeInvestmentRecords.reduce((acc, curr) => acc + curr.GP, 0);
  const activeInv = activeInvestmentRecords.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0);

  const realRatio = activeGP > 0 ? (activeInv / activeGP) : 0;

  /**
   * Formateador: Muestra valores en miles para mejor lectura
   */
  const formatInThousands = (val: number) => {
    return `$${Math.round(val / 1000).toLocaleString()}k`;
  };

  /**
   * Cálculo de Real Index: Ajustado a 2 decimales para mostrar formato X.XX
   */
  const realIndexValue = ((realRatio * 10) / 100).toFixed(2);

  const kpiList = [
    { label: 'Ton. Métricas', value: Math.round(totalTons / 1000).toLocaleString(), sub: 'Volumen (TON x1000)', icon: Weight, color: 'bg-amber-500' },
    { label: 'Margen Bruto', value: formatInThousands(totalGM), sub: 'Rentabilidad (GM)', icon: DollarSign, color: 'bg-emerald-500' },
    { label: 'Utilidad Bruta', value: formatInThousands(totalGP), sub: 'Beneficio Bruto (GP)', icon: TrendingUp, color: 'bg-blue-600' },
    { label: 'Inversión Lab', value: formatInThousands(totalInv), sub: 'Activos Totales (INV)', icon: FlaskConical, color: 'bg-violet-600' },
    { label: 'Índice Real', value: realIndexValue, sub: 'Score de Eficiencia', icon: Target, color: 'bg-teal-600' },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
      {kpiList.map((kpi, idx) => (
        <div key={idx} className={`${kpi.color} p-5 rounded-2xl shadow-xl shadow-slate-200/50 text-white flex flex-col justify-between transform hover:-translate-y-1 transition-all duration-300`}>
          <div className="flex justify-between items-start mb-4">
            <div className="p-2 bg-white/20 rounded-xl">
              <kpi.icon size={20} />
            </div>
            <span className="text-[10px] font-bold uppercase tracking-widest opacity-70">
              {kpi.sub}
            </span>
          </div>
          <div>
            <p className="text-2xl font-extrabold tracking-tight">{kpi.value}</p>
            <h3 className="text-xs font-semibold mt-1 opacity-90">{kpi.label}</h3>
          </div>
        </div>
      ))}
    </div>
  );
};

import React, { useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell, PieChart, Pie, LabelList
} from 'recharts';
import { FinancialRecord } from '../types';
import { MONTHS } from '../utils/dataProcessor';

interface ChartsProps {data: FinancialRecord[];}

export const Charts: React.FC<ChartsProps> = ({ data }) => {
  // 1. Trend Data for Monthly Charts
  const trendData = useMemo(() => {
    const grouped = MONTHS.map(m => {
      const filtered = data.filter(d => d.Fecha.toUpperCase() === m);
      return {
        month: m.substring(0, 3),
        gp: filtered.reduce((acc, curr) => acc + curr.GP, 0),
        labInv: filtered.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0),
      };
    }).filter(d => d.gp > 0 || d.labInv > 0);
    return grouped;
  }, [data]);

  // 2. Investment Distribution for Donut Chart
  const distributionData = useMemo(() => {
    const lab = data.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0);
    const nir = data.reduce((acc, curr) => acc + curr['Inversion Nir'], 0);
    const mico = data.reduce((acc, curr) => acc + curr['Inversion equipos Micotoxinas'], 0);
    return [
      { name: 'Laboratorio Análisis', value: lab, color: '#3b82f6' },
      { name: 'NIR', value: nir, color: '#10b981' },
      { name: 'Micotoxinas', value: mico, color: '#f59e0b' }
    ];
  }, [data]);

  // 3. High Risk Ratio (>8%) Bar Chart Data
  const highRiskData = useMemo(() => {
    const clientGroups = data.reduce((acc, curr) => {
      const name = curr['nombre cliente'];
      if (!acc[name]) acc[name] = { gp: 0, inv: 0 };
      acc[name].gp += curr.GP;
      acc[name].inv += (curr.totalInversion || 0);
      return acc;
    }, {} as Record<string, { gp: number; inv: number }>);

    return Object.keys(clientGroups)
      .map(name => {
        const group = clientGroups[name];
        const rawRatio = group.gp > 0 ? (group.inv / group.gp) * 100 : 0;
        const displayRatio = rawRatio / 1000;
        return { name, ratio: displayRatio, rawRatio };
      })
      .filter(item => item.rawRatio > 8)
      .sort((a, b) => b.rawRatio - a.rawRatio)
      .slice(0, 10); 
  }, [data]);

  // 4. Average Investment by Classification
  const classificationData = useMemo(() => {
    const groups: Record<string, { total: number; count: number }> = {};
    data.forEach(item => {
      const cls = item.clasificacion || 'N/A';
      if (!groups[cls]) groups[cls] = { total: 0, count: 0 };
      groups[cls].total += (item.totalInversion || 0);
      groups[cls].count += 1;
    });
    return Object.entries(groups).map(([name, stats]) => ({
      name: `Clase ${name}`,
      avg: stats.count > 0 ? stats.total / stats.count : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
  }, [data]);

  const formatCurrency = (value: number) => `$${Math.round(value).toLocaleString()}`;
  const formatPercent = (value: number) => `${value.toFixed(2)}%`;

  return (
    <div className="space-y-8">
      {/* Row 1: Main Trends */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* GP Trend */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-blue-600 rounded-full"></span>
            Tendencia Mensual de Utilidad Bruta
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorGp" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "GP"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Area type="monotone" dataKey="gp" stroke="#2563eb" strokeWidth={2.5} fillOpacity={1} fill="url(#colorGp)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Lab Investment Trend */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-violet-500 rounded-full"></span>
            Tendencia de Inversión en Lab
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={trendData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "Inversión Lab"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="labInv" fill="#8b5cf6" radius={[6, 6, 0, 0]} barSize={32} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Row 2: Allocation and Avg Inv */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-emerald-500 rounded-full"></span>
            Distribución de Activos
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={distributionData}
                  cx="50%"
                  cy="45%"
                  innerRadius={65}
                  outerRadius={85}
                  paddingAngle={8}
                  dataKey="value"
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                  labelLine={{ stroke: '#cbd5e1', strokeWidth: 1 }}
                >
                  {distributionData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip formatter={(value: number) => formatCurrency(value)} />
                <Legend verticalAlign="bottom" align="center" iconType="circle" wrapperStyle={{ paddingTop: '20px', fontSize: '11px', color: '#64748b' }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-indigo-500 rounded-full"></span>
            Inversión Promedio por Clasificación
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={classificationData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 11, fill: '#64748b', fontWeight: 600}} />
                <YAxis hide />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "Inv. Promedio"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="avg" fill="#6366f1" radius={[8, 8, 0, 0]} barSize={40}>
                  <LabelList 
                    dataKey="avg" 
                    position="top" 
                    formatter={(v: number) => `$${Math.round(v/1000)}k`}
                    style={{ fontSize: '10px', fontWeight: 'bold', fill: '#6366f1' }}
                  />
                  {classificationData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#6366f1' : '#818cf8'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Row 3: Risk Profile */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
        <div className="flex items-center justify-between mb-6">
          <h3 className="text-sm font-bold text-slate-800 flex items-center gap-2">
            <span className="w-2 h-2 bg-rose-500 rounded-full animate-pulse"></span>
            Ratios Críticos de Inversión por Cliente
          </h3>
          <div className="flex flex-col items-end">
             <span className="text-[10px] font-bold text-rose-600 bg-rose-50 px-3 py-1 rounded-full border border-rose-100 uppercase mb-1">
              {highRiskData.length} Cuentas Marcadas
            </span>
            <span className="text-[9px] text-slate-400 font-bold uppercase tracking-wider">Ratio = (Inv/GP)*100 / 1000</span>
          </div>
        </div>
        <div className="flex-1 w-full">
          {highRiskData.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={highRiskData} layout="vertical" margin={{ left: 40, right: 30 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                <XAxis type="number" hide domain={[0, 'auto']} />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={140} 
                  tick={{fontSize: 10, fill: '#64748b', fontWeight: 600}} 
                  axisLine={false} 
                  tickLine={false} 
                />
                <Tooltip 
                  formatter={(value: number) => [formatPercent(value), "Ratio Visual"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="ratio" radius={[0, 6, 6, 0]} barSize={22}>
                   <LabelList dataKey="ratio" position="right" formatter={(v: number) => `${v.toFixed(2)}%`} style={{ fontSize: '10px', fill: '#f43f5e', fontWeight: 'bold' }} />
                  {highRiskData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill="#f43f5e" />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 text-xs italic space-y-2">
              <p>✅ Todas las cuentas dentro de umbrales saludables.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { FinancialRecord } from '../types';
import { AlertCircle, TrendingUp } from 'lucide-react';

interface DataTableProps {
  data: FinancialRecord[];
}

export const DataTable: React.FC<DataTableProps> = ({ data }) => {
  const clientGroups = data.reduce((acc, curr) => {
    const name = curr['nombre cliente'];
    if (!acc[name]) acc[name] = { gp: 0, inv: 0 };
    acc[name].gp += curr.GP;
    acc[name].inv += (curr.totalInversion || 0);
    return acc;
  }, {} as Record<string, { gp: number; inv: number }>);

  const riskClients = Object.keys(clientGroups).map(name => {
    const group = clientGroups[name];
    const ratio = group.gp > 0 ? (group.inv / group.gp) * 100 : 0;
    return { name, ...group, ratio };
  }).sort((a, b) => b.ratio - a.ratio);

  const highRisk = riskClients.filter(c => c.ratio > 8);

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden flex flex-col h-full">
      <div className="p-6 border-b border-slate-50 flex items-center justify-between bg-slate-50/50">
        <div className="flex items-center gap-3">
          <div className="bg-rose-100 p-2 rounded-lg text-rose-600">
            <AlertCircle size={20} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-800">Cuentas con Alto Ratio de Inversión</h3>
            <p className="text-xs text-slate-500 font-medium">Clientes que superan el umbral recomendado del 8.0%</p>
          </div>
        </div>
        <span className="bg-rose-50 text-rose-700 px-3 py-1 rounded-full text-xs font-bold border border-rose-100">
          {highRisk.length} Marcados
        </span>
      </div>

      <div className="flex-1 overflow-auto max-h-[400px]">
        <table className="w-full text-left border-collapse">
          <thead className="sticky top-0 bg-white shadow-sm z-10">
            <tr>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50">Nombre de la Cuenta</th>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50">Utilidad Bruta (GP)</th>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50">Inversión Lab</th>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50">Ratio</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {highRisk.length > 0 ? (
              highRisk.map((client, idx) => (
                <tr key={idx} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4 text-sm font-bold text-slate-700 group-hover:text-blue-600">{client.name}</td>
                  <td className="px-6 py-4 text-sm font-medium text-slate-600">${Math.round(client.gp).toLocaleString()}</td>
                  <td className="px-6 py-4 text-sm font-medium text-slate-600">${Math.round(client.inv).toLocaleString()}</td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-bold text-rose-600">{(client.ratio / 1000).toFixed(2)}%</span>
                      <TrendingUp size={14} className="text-rose-400" />
                    </div>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={4} className="px-6 py-12 text-center text-slate-400 text-sm font-medium italic">
                  Salud financiera excelente. No hay cuentas que superen el umbral del 8%.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { KPIs } from './components/KPIs';
import { Charts } from './components/Charts';
import { DataTable } from './components/DataTable';
import { FinancialRecord } from './types';
import { processRawData, getBackupData } from './utils/dataProcessor';
import { LayoutDashboard, Menu, X } from 'lucide-react';

const App: React.FC = () => {
  const [allData, setAllData] = useState<FinancialRecord[]>([]);
  const [filteredData, setFilteredData] = useState<FinancialRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // Initialize with backup data
  useEffect(() => {
    const data = processRawData(getBackupData());
    setAllData(data);
    setFilteredData(data);
    setIsLoading(false);
  }, []);

  const handleDataUpdate = (newData: any[]) => {
    setIsLoading(true);
    const processed = processRawData(newData);
    setAllData(processed);
    setFilteredData(processed);
    setIsLoading(false);
  };

  const handleFilterChange = (filters: {
    year: string;
    client: string;
    classification: string;
    months: string[];
  }) => {
    const filtered = allData.filter((item) => {
      const yearMatch = filters.year === 'all' || item.año.toString() === filters.year;
      const clientMatch = filters.client === 'all' || item['nombre cliente'] === filters.client;
      const classMatch = filters.classification === 'all' || item.clasificacion === filters.classification;
      const monthMatch = filters.months.length === 0 || filters.months.includes(item.Fecha.toUpperCase());
      return yearMatch && clientMatch && classMatch && monthMatch;
    });
    setFilteredData(filtered);
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden text-slate-900">
      {/* Sidebar con transiciones */}
      <div className={`fixed inset-y-0 left-0 z-30 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 transition-all duration-300 ease-in-out`}>
        <Sidebar 
          allData={allData} 
          onFilterChange={handleFilterChange} 
          onDataUpload={handleDataUpdate}
          onClose={() => setIsSidebarOpen(false)}
          isOpen={isSidebarOpen}
        />
      </div>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden w-full">
        {/* Header */}
        <header className="bg-white border-b border-slate-200 px-8 py-4 flex items-center justify-between shadow-sm z-10">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-100 rounded-lg transition-colors text-slate-600 lg:hidden"
            >
              <Menu size={24} />
            </button>
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-100 rounded-lg transition-colors text-slate-600 hidden lg:block"
            >
              {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-lg">
                <LayoutDashboard className="text-white w-6 h-6" />
              </div>
              <div>
                <h1 className="text-xl font-bold text-slate-800">Pilar Control Laboratorio</h1>
                <p className="text-xs text-slate-500 font-medium">Panel de Rendimiento Empresarial</p>
              </div>
            </div>
          </div>

