export const generateBusinessInsights = async (data: FinancialRecord[]): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const summaryData = data.slice(0, 15).map(item => ({
      cliente: item['nombre cliente'],
      utilidad: item.GP,
      toneladas: item.TON,
      ratio: (item['% Inversion Lab'] || 0) * 100
    }));

    const totalGP = data.reduce((acc, curr) => acc + curr.GP, 0);
    const totalInv = data.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0);
    const globalRatio = totalGP > 0 ? (totalInv / totalGP) * 100 : 0;

    const prompt = `
      Actúa como un Analista Financiero Senior. Analiza estos datos de rendimiento empresarial:
      - Cantidad de registros: ${data.length}
      - Utilidad Bruta Total (GP): $${totalGP.toLocaleString()}
      - Inversión Total: $${totalInv.toLocaleString()}
      - Ratio Global de Inversión: ${globalRatio.toFixed(2)}%

      Muestra de Rendimiento por Cliente:
      ${JSON.stringify(summaryData)}

      Por favor, responde en ESPAÑOL y proporciona:
      1. Un resumen conciso de la salud financiera actual.
      2. Identificación de clientes de alto riesgo (donde el ratio de inversión supere el 8%).
      3. Recomendaciones estratégicas accionables para mejorar el retorno de inversión (ROI).

      Utiliza un formato Markdown profesional. Mantén la respuesta breve y de alto impacto.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
    });

    return response.text || "No se han podido generar análisis en este momento.";
  } catch (error) {
    console.error("Error en API Gemini:", error);
    return "Error al generar el análisis. Por favor, asegúrese de que su clave de API es válida.";
  }
};

import React from 'react';
import { FinancialRecord } from '../types';
import { Weight, DollarSign, TrendingUp, FlaskConical, Target } from 'lucide-react';

interface KPIsProps {
  data: FinancialRecord[];
}

export const KPIs: React.FC<KPIsProps> = ({ data }) => {
  const sum = (key: keyof FinancialRecord) => data.reduce((acc, curr) => acc + (Number(curr[key]) || 0), 0);

  const totalTons = sum('TON');
  const totalGM = sum('GM');
  const totalGP = sum('GP');
  const totalInv = sum('totalInversion');

  // Calculating Real Ratio (only for clients with investment > 0)
  const activeInvestmentRecords = data.filter(d => (d.totalInversion || 0) > 0);
  const activeGP = activeInvestmentRecords.reduce((acc, curr) => acc + curr.GP, 0);
  const activeInv = activeInvestmentRecords.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0);

  const realRatio = activeGP > 0 ? (activeInv / activeGP) : 0;

  /**
   * Formateador para valores monetarios: Muestra valores contraídos en miles para lectura rápida
   */
  const formatInThousands = (val: number) => {
    return `$${Math.round(val / 1000).toLocaleString()}k`;
  };

  /**
   * Cálculo de Real Index: Ajustado a 2 decimales para mostrar formato X.XX
   */
  const realIndexValue = ((realRatio * 10) / 100).toFixed(2);

  const kpiList = [
    { 
      label: 'Ton. Métricas', 
      // Se muestra el valor completo con separadores de miles y sin dividir por 1000
      value: Math.round(totalTons).toLocaleString(), 
      sub: 'Volumen Total (TON)', 
      icon: Weight, 
      color: 'bg-amber-500' 
    },
    { label: 'Margen Bruto', value: formatInThousands(totalGM), sub: 'Rentabilidad (GM)', icon: DollarSign, color: 'bg-emerald-500' },
    { label: 'Utilidad Bruta', value: formatInThousands(totalGP), sub: 'Beneficio Bruto (GP)', icon: TrendingUp, color: 'bg-blue-600' },
    { label: 'Inversión Lab', value: formatInThousands(totalInv), sub: 'Activos Totales (INV)', icon: FlaskConical, color: 'bg-violet-600' },
    { label: 'Índice Real', value: realIndexValue, sub: 'Score de Eficiencia', icon: Target, color: 'bg-teal-600' },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
      {kpiList.map((kpi, idx) => (
        <div key={idx} className={`${kpi.color} p-5 rounded-2xl shadow-xl shadow-slate-200/50 text-white flex flex-col justify-between transform hover:-translate-y-1 transition-all duration-300`}>
          <div className="flex justify-between items-start mb-4">
            <div className="p-2 bg-white/20 rounded-xl">
              <kpi.icon size={20} />
            </div>
            <span className="text-[10px] font-bold uppercase tracking-widest opacity-70">
              {kpi.sub}
            </span>
          </div>
          <div>
            <p className="text-2xl font-extrabold tracking-tight">{kpi.value}</p>
            <h3 className="text-xs font-semibold mt-1 opacity-90">{kpi.label}</h3>
          </div>
        </div>
      ))}
    </div>
  );
};

import React, { useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell, PieChart, Pie, LabelList
} from 'recharts';
import { FinancialRecord } from '../types';
import { MONTHS } from '../utils/dataProcessor';

interface ChartsProps {data: FinancialRecord[];}

export const Charts: React.FC<ChartsProps> = ({ data }) => {
  // 1. Trend Data for Monthly Charts
  const trendData = useMemo(() => {
    const grouped = MONTHS.map(m => {
      const filtered = data.filter(d => d.Fecha.toUpperCase() === m);
      return {
        month: m.substring(0, 3),
        gp: filtered.reduce((acc, curr) => acc + curr.GP, 0),
        // Cambiado para usar totalInversion en lugar de solo analisis lab
        labInv: filtered.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0),
      };
    }).filter(d => d.gp > 0 || d.labInv > 0);
    return grouped;
  }, [data]);

  // 2. Investment Distribution for Donut Chart
  const distributionData = useMemo(() => {
    const lab = data.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0);
    const nir = data.reduce((acc, curr) => acc + curr['Inversion Nir'], 0);
    const mico = data.reduce((acc, curr) => acc + curr['Inversion equipos Micotoxinas'], 0);
    return [
      { name: 'Laboratorio Análisis', value: lab, color: '#3b82f6' },
      { name: 'NIR', value: nir, color: '#10b981' },
      { name: 'Micotoxinas', value: mico, color: '#f59e0b' }
    ];
  }, [data]);

  // 3. High Risk Ratio (>8%) Bar Chart Data
  const highRiskData = useMemo(() => {
    const clientGroups = data.reduce((acc, curr) => {
      const name = curr['nombre cliente'];
      if (!acc[name]) acc[name] = { gp: 0, inv: 0 };
      acc[name].gp += curr.GP;
      acc[name].inv += (curr.totalInversion || 0);
      return acc;
    }, {} as Record<string, { gp: number; inv: number }>);

    return Object.keys(clientGroups)
      .map(name => {
        const group = clientGroups[name];
        const rawRatio = group.gp > 0 ? (group.inv / group.gp) * 100 : 0;
        const displayRatio = rawRatio / 1000;
        return { name, ratio: displayRatio, rawRatio };
      })
      .filter(item => item.rawRatio > 8)
      .sort((a, b) => b.rawRatio - a.rawRatio)
      .slice(0, 10); 
  }, [data]);

  // 4. Average Investment by Classification
  const classificationData = useMemo(() => {
    const groups: Record<string, { total: number; count: number }> = {};
    data.forEach(item => {
      const cls = item.clasificacion || 'N/A';
      if (!groups[cls]) groups[cls] = { total: 0, count: 0 };
      groups[cls].total += (item.totalInversion || 0);
      groups[cls].count += 1;
    });
    return Object.entries(groups).map(([name, stats]) => ({
      name: `Clase ${name}`,
      avg: stats.count > 0 ? stats.total / stats.count : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
  }, [data]);

  const formatCurrency = (value: number) => `$${Math.round(value).toLocaleString()}`;
  const formatPercent = (value: number) => `${value.toFixed(2)}%`;

  return (
    <div className="space-y-8">
      {/* Row 1: Main Trends */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* GP Trend */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-blue-600 rounded-full"></span>
            Tendencia Mensual de Utilidad Bruta
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorGp" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "GP"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Area type="monotone" dataKey="gp" stroke="#2563eb" strokeWidth={2.5} fillOpacity={1} fill="url(#colorGp)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Lab Investment Trend */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-violet-500 rounded-full"></span>
            Tendencia de Inversión Total Lab
          </h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={trendData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip 
                  formatter={(value: number) => [formatCurrency(value), "Inversión Total"]}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="labInv" fill="#8b5cf6" radius={[6, 6, 0, 0]} barSize={32} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Row 2: Allocation and Avg Inv */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[380px]">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
