                <Bar dataKey="avg" fill="#6366f1" radius={[8, 8, 0, 0]} barSize={40}>
                  <LabelList 
                    dataKey="avg" 
                    position="top" 
                    formatter={(v: number) => `$${Math.round(v/1000)}k`}
