import React from 'react';
import { FinancialRecord } from '../types';
import { Weight, DollarSign, TrendingUp, FlaskConical, Target } from 'lucide-react';

interface KPIsProps {
  data: FinancialRecord[];
}

export const KPIs: React.FC<KPIsProps> = ({ data }) => {
  const sum = (key: keyof FinancialRecord) => data.reduce((acc, curr) => acc + (Number(curr[key]) || 0), 0);

  const totalTons = sum('TON');
  const totalGM = sum('GM');
  const totalGP = sum('GP');
  const totalInv = sum('totalInversion');

  // Calculating Real Ratio (only for clients with investment > 0)
  const activeInvestmentRecords = data.filter(d => (d.totalInversion || 0) > 0);
  const activeGP = activeInvestmentRecords.reduce((acc, curr) => acc + curr.GP, 0);
  const activeInv = activeInvestmentRecords.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0);

  const realRatio = activeGP > 0 ? (activeInv / activeGP) : 0;

  /**
   * Formateador inteligente: Detecta si el valor debe mostrarse en Millones (M) o Miles (k)
   */
  const formatSmartCurrency = (val: number) => {
    if (Math.abs(val) >= 1000000) {
      return `$${(val / 1000000).toLocaleString(undefined, { minimumFractionDigits: 1, maximumFractionDigits: 1 })}M`;
    }
    return `$${Math.round(val / 1000).toLocaleString()}k`;
  };

  /**
   * Cálculo de Real Index: Ajustado a 2 decimales para mostrar formato X.XX
   */
  const realIndexValue = ((realRatio * 10) / 100).toFixed(2);

  const kpiList = [
    { 
      label: 'Ton. Métricas', 
      value: Math.round(totalTons).toLocaleString(), 
      sub: 'Volumen Total (TON)', 
      icon: Weight, 
      color: 'bg-amber-500' 
    },
