  // CÁLCULO ÍNDICE REAL: Promedio de (Columna Q / Columna L) para clientes con servicio
  const averageRatio = activeRecords.length > 0 
    ? activeRecords.reduce((acc, curr) => acc + ((curr.totalInversion || 0) / curr.GP), 0) / activeRecords.length
    : 0;

  const formatSmartCurrency = (val: number) => {
    const absVal = Math.abs(val);
    if (absVal >= 1000000) {
      return `$${(val / 1000000).toLocaleString(undefined, { minimumFractionDigits: 1, maximumFractionDigits: 1 })}M`;
    }
    if (absVal >= 1000) {
      return `$${Math.round(val / 1000).toLocaleString()}k`;
    }
    return `$${val.toLocaleString()}`;
  };

  const kpiList = [
    { 
      label: 'Ton. Métricas', 
      value: Math.round(totalTons).toLocaleString(), 
      sub: 'Volumen Total (TON)', 
      icon: Weight, 
      color: 'bg-amber-500' 
    },
    { 
      label: 'Margen Bruto', 
      value: formatSmartCurrency(totalGM), 
      sub: 'Rentabilidad (GM - Col J)', 
      icon: DollarSign, 
      color: 'bg-emerald-500' 
    },
    { 
      label: 'Utilidad Bruta', 
      value: formatSmartCurrency(totalGP), 
      sub: 'Beneficio Bruto (GP)', 
      icon: TrendingUp, 
      color: 'bg-blue-600' 
    },
    { 
      label: 'Inversión Lab', 
      value: formatSmartCurrency(totalInv), 
      sub: 'Total Columna Q (INV)', 
      icon: FlaskConical, 
      color: 'bg-violet-600' 
    },
    { 
      label: 'Índice Real', 
      value: averageRatio.toLocaleString(undefined, { minimumFractionDigits: 4, maximumFractionDigits: 4 }), 
      sub: 'Promedio Ratio Q/L', 
      icon: Target, 
      color: 'bg-teal-600' 
    },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
      {kpiList.map((kpi, idx) => (
        <div key={idx} className={`${kpi.color} p-5 rounded-2xl shadow-xl shadow-slate-200/50 text-white flex flex-col justify-between transform hover:-translate-y-1 transition-all duration-300`}>
          <div className="flex justify-between items-start mb-4">
            <div className="p-2 bg-white/20 rounded-xl">
              <kpi.icon size={20} />
            </div>
            <span className="text-[10px] font-bold uppercase tracking-widest opacity-70">
              {kpi.sub}
            </span>
          </div>
          <div>
            <p className="text-2xl font-extrabold tracking-tight">{kpi.value}</p>
            <h3 className="text-xs font-semibold mt-1 opacity-90">{kpi.label}</h3>
          </div>
        </div>
      ))}
    </div>
  );
};

import React, { useMemo } from 'react';
