}

export const KPIs: React.FC<KPIsProps> = ({ data }) => {
  // Suma los valores de la propiedad indicada para los datos actualmente filtrados
  const sum = (key: keyof FinancialRecord) => 
    data.reduce((acc, curr) => {
      const val = curr[key];
      return acc + (typeof val === 'number' ? val : 0);
    }, 0);

  const totalTons = sum('TON');
  const totalGM = sum('GM'); // Corresponde a Columna J (Margen Bruto)
  const totalGP = sum('GP'); // Corresponde a Columna L (Utilidad Bruta)
  const totalInv = sum('totalInversion'); // Corresponde a Columna Q

  // FILTRADO: Solo registros que tienen servicios de laboratorio (inversion > 0)
  const activeRecords = data.filter(d => (d.totalInversion || 0) > 0 && (d.GP || 0) !== 0);

  // CÁLCULO ÍNDICE REAL: Promedio de (Columna Q / Columna L) para clientes con servicio
  const averageRatio = activeRecords.length > 0 
    ? activeRecords.reduce((acc, curr) => acc + ((curr.totalInversion || 0) / curr.GP), 0) / activeRecords.length
    : 0;

  const formatSmartCurrency = (val: number) => {
    const absVal = Math.abs(val);
    // Para Millones: agregamos 2 dígitos más (de 1 a 3 decimales)
    if (absVal >= 1000000) {
      return `$${(val / 1000000).toLocaleString(undefined, { minimumFractionDigits: 3, maximumFractionDigits: 3 })}M`;
    }
    // Para Miles: agregamos 2 dígitos decimales (antes era redondeo entero)
    if (absVal >= 1000) {
      return `$${(val / 1000).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}k`;
    }
    return `$${val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
