import React from 'react';
import { FinancialRecord } from '../types';
import { AlertCircle, TrendingUp, DollarSign } from 'lucide-react';

interface DataTableProps {
  data: FinancialRecord[];
}

export const DataTable: React.FC<DataTableProps> = ({ data }) => {
  // Agrupar por cliente para mostrar totales de rentabilidad
  const clientGroups = data.reduce((acc, curr) => {
    const name = curr['nombre cliente'];
    if (!acc[name]) acc[name] = { gm: 0, gp: 0, inv: 0 };
    acc[name].gm += curr.GM;
    acc[name].gp += curr.GP;
    acc[name].inv += (curr.totalInversion || 0);
    return acc;
  }, {} as Record<string, { gm: number; gp: number; inv: number }>);

  const riskClients = Object.keys(clientGroups).map(name => {
    const group = clientGroups[name];
    const ratio = group.gp > 0 ? (group.inv / group.gp) * 100 : 0;
    return { name, ...group, ratio };
  }).sort((a, b) => b.ratio - a.ratio);

  // Consideramos "Riesgo" si el ratio supera el 8%
  const highRisk = riskClients.filter(c => c.ratio > 8);
  const displayClients = riskClients.length > 0 ? riskClients : [];

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden flex flex-col h-full">
      <div className="p-6 border-b border-slate-50 flex items-center justify-between bg-slate-50/50">
        <div className="flex items-center gap-3">
          <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
            <DollarSign size={20} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-800">Desglose de Rentabilidad por Cliente</h3>
            <p className="text-xs text-slate-500 font-medium">Análisis detallado de GM (Col J) y GP (Col L)</p>
          </div>
        </div>
        <div className="flex gap-2">
          {highRisk.length > 0 && (
            <span className="bg-rose-50 text-rose-700 px-3 py-1 rounded-full text-xs font-bold border border-rose-100 flex items-center gap-1">
              <AlertCircle size={12} /> {highRisk.length} Ratios Altos
            </span>
          )}
        </div>
      </div>

      <div className="flex-1 overflow-auto max-h-[500px]">
        <table className="w-full text-left border-collapse">
          <thead className="sticky top-0 bg-white shadow-sm z-10">
            <tr>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50">Cliente</th>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50 text-right">Margen Bruto (GM)</th>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50 text-right">Utilidad Bruta (GP)</th>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50 text-right">Inv. Lab (Q)</th>
              <th className="px-6 py-4 text-[10px] font-extrabold text-slate-400 uppercase tracking-widest border-b border-slate-50 text-center">Ratio % (Q/L)</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {displayClients.length > 0 ? (
              displayClients.map((client, idx) => {
                const isHighRisk = client.ratio > 8;
                return (
                  <tr key={idx} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-6 py-4 text-sm font-bold text-slate-700 group-hover:text-blue-600">
                      {client.name}
                    </td>
                    <td className="px-6 py-4 text-sm font-bold text-emerald-600 text-right">
                      ${Math.round(client.gm).toLocaleString()}
                    </td>
                    <td className="px-6 py-4 text-sm font-medium text-slate-600 text-right">
                      ${Math.round(client.gp).toLocaleString()}
                    </td>
                    <td className="px-6 py-4 text-sm font-medium text-slate-600 text-right">
                      ${Math.round(client.inv).toLocaleString()}
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center justify-center gap-2">
                        <span className={`text-sm font-bold ${isHighRisk ? 'text-rose-600' : 'text-slate-500'}`}>
                          {client.ratio.toFixed(4)}%
                        </span>
                        {isHighRisk && <TrendingUp size={14} className="text-rose-400" />}
                      </div>
                    </td>
                  </tr>
                );
              })
            ) : (
              <tr>
                <td colSpan={5} className="px-6 py-12 text-center text-slate-400 text-sm font-medium italic">
                  No hay datos disponibles para la selección actual.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell, PieChart, Pie, LabelList, ReferenceLine, Label
} from 'recharts';
import { FinancialRecord } from '../types';
import { MONTHS } from '../utils/dataProcessor';

interface ChartsProps {data: FinancialRecord[];}

export const Charts: React.FC<ChartsProps> = ({ data }) => {
  // 1. Tendencia Mensual - Basada estrictamente en los datos filtrados
  const trendData = useMemo(() => {
    return MONTHS.map(m => {
      const recordsInMonth = data.filter(d => d.Fecha.toUpperCase() === m);
      return {
        month: m.substring(0, 3),
        gp: recordsInMonth.reduce((acc, curr) => acc + curr.GP, 0),
        labInv: recordsInMonth.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0),
        ton: recordsInMonth.reduce((acc, curr) => acc + curr.TON, 0),
      };
    }).filter(d => d.gp !== 0 || d.labInv !== 0 || d.ton !== 0);
  }, [data]);

  // 2. Distribución de Inversión
  const distributionData = useMemo(() => {
    const lab = data.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0);
    const nir = data.reduce((acc, curr) => acc + curr['Inversion Nir'], 0);
    const mico = data.reduce((acc, curr) => acc + curr['Inversion equipos Micotoxinas'], 0);
    return [
      { name: 'Lab Análisis', value: lab, color: '#3b82f6' },
      { name: 'NIR', value: nir, color: '#10b981' },
      { name: 'Micotoxinas', value: mico, color: '#f59e0b' }
    ].filter(d => d.value > 0);
  }, [data]);

  // 3. Ratios por Cliente (Sincronizado con selección)
  const riskData = useMemo(() => {
    const clientGroups = data.reduce((acc, curr) => {
      const name = curr['nombre cliente'];
      if (!acc[name]) acc[name] = { gp: 0, inv: 0 };
      acc[name].gp += curr.GP;
      acc[name].inv += (curr.totalInversion || 0);
      return acc;
    }, {} as Record<string, { gp: number; inv: number }>);

    return Object.keys(clientGroups)
      .map(name => {
        const group = clientGroups[name];
        const rawRatio = group.gp !== 0 ? (group.inv / group.gp) * 100 : 0;
        return { name, ratio: rawRatio, rawRatio };
      })
      .sort((a, b) => b.ratio - a.ratio)
      .slice(0, 15); 
  }, [data]);

  // 4. Inversión por Clasificación
  const classificationData = useMemo(() => {
    const groups: Record<string, { total: number; count: number }> = {};
    data.forEach(item => {
      const cls = item.clasificacion || 'N/A';
      if (!groups[cls]) groups[cls] = { total: 0, count: 0 };
      groups[cls].total += (item.totalInversion || 0);
      groups[cls].count += 1;
    });

    return Object.entries(groups).map(([name, stats]) => ({
      name: `Clase ${name}`,
      avg: stats.count > 0 ? stats.total / stats.count : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
  }, [data]);

  const formatCurrency = (value: number) => `$${value.toLocaleString(undefined, {minimumFractionDigits: 0, maximumFractionDigits: 0})}`;

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Gráfico Tendencia GP */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-blue-600 rounded-full"></span>
            Utilidad Bruta Mensual (GP)
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorGp" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip formatter={(value: number) => [formatCurrency(value), "GP"]} />
                <Area type="monotone" dataKey="gp" stroke="#2563eb" strokeWidth={3} fill="url(#colorGp)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Gráfico Inversión Lab */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-violet-500 rounded-full"></span>
            Inversión Total por Mes (Q)
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={trendData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip formatter={(value: number) => [formatCurrency(value), "Inversión"]} />
                <Bar dataKey="labInv" fill="#8b5cf6" radius={[6, 6, 0, 0]} barSize={35} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-emerald-500 rounded-full"></span>
            Desglose de Activos de Inversión
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={distributionData}
                  cx="50%" cy="45%" innerRadius={60} outerRadius={85} paddingAngle={5}
                  dataKey="value"
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                >
                  {distributionData.map((entry, index) => <Cell key={index} fill={entry.color} />)}
                </Pie>
                <Tooltip formatter={(v: number) => formatCurrency(v)} />
                <Legend verticalAlign="bottom" iconType="circle" />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-indigo-500 rounded-full"></span>
            Inversión Promedio por Clase
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={classificationData} margin={{ top: 20 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 11, fill: '#64748b'}} />
                <YAxis hide />
                <Tooltip formatter={(v: number) => formatCurrency(v)} />
                <Bar dataKey="avg" fill="#6366f1" radius={[8, 8, 0, 0]} barSize={45}>
                  <LabelList dataKey="avg" position="top" formatter={(v: number) => `$${Math.round(v/1000)}k`} style={{fontSize: 10, fill: '#6366f1', fontWeight: 'bold'}} />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[400px] flex flex-col">
        <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
          <span className="w-2 h-2 bg-rose-500 rounded-full"></span>
          Ratio de Inversión por Cliente (% Utilidad)
        </h3>
        <div className="flex-1">
          {riskData.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={riskData} layout="vertical" margin={{ left: 50, right: 30 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
