import React, { useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell, PieChart, Pie, LabelList, ReferenceLine, Label
} from 'recharts';
import { FinancialRecord } from '../types';
import { MONTHS } from '../utils/dataProcessor';

interface ChartsProps {data: FinancialRecord[];}

export const Charts: React.FC<ChartsProps> = ({ data }) => {
  // 1. Tendencia Mensual - Basada estrictamente en los datos filtrados
  const trendData = useMemo(() => {
    return MONTHS.map(m => {
      const recordsInMonth = data.filter(d => d.Fecha.toUpperCase() === m);
      return {
        month: m.substring(0, 3),
        gp: recordsInMonth.reduce((acc, curr) => acc + curr.GP, 0),
        labInv: recordsInMonth.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0),
        ton: recordsInMonth.reduce((acc, curr) => acc + curr.TON, 0),
      };
    }).filter(d => d.gp !== 0 || d.labInv !== 0 || d.ton !== 0);
  }, [data]);

  // Cálculo del promedio de inversión para la línea de referencia
  const avgLabInv = useMemo(() => {
    if (trendData.length === 0) return 0;
    const total = trendData.reduce((acc, curr) => acc + curr.labInv, 0);
    return total / trendData.length;
  }, [trendData]);

  // 2. Distribución de Inversión
  const distributionData = useMemo(() => {
    const lab = data.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0);
    const nir = data.reduce((acc, curr) => acc + curr['Inversion Nir'], 0);
    const mico = data.reduce((acc, curr) => acc + curr['Inversion equipos Micotoxinas'], 0);
    return [
      { name: 'Lab Análisis', value: lab, color: '#3b82f6' },
      { name: 'NIR', value: nir, color: '#10b981' },
      { name: 'Micotoxinas', value: mico, color: '#f59e0b' }
    ].filter(d => d.value > 0);
  }, [data]);

  // 3. Ratios por Cliente (Sincronizado con selección)
  const riskData = useMemo(() => {
    const clientGroups = data.reduce((acc, curr) => {
      const name = curr['nombre cliente'];
      if (!acc[name]) acc[name] = { gp: 0, inv: 0 };
      const group = acc[name]!;
      group.gp += curr.GP;
      group.inv += (curr.totalInversion || 0);
      return acc;
    }, {} as Record<string, { gp: number; inv: number }>);

    return Object.keys(clientGroups)
      .map(name => {
        const group = clientGroups[name]!;
        const rawRatio = group.gp !== 0 ? (group.inv / group.gp) * 100 : 0;
        return { name, ratio: rawRatio, rawRatio };
      })
      .sort((a, b) => b.ratio - a.ratio)
      .slice(0, 10);
  }, [data]);

  // 4. Top 10 Clientes por GP
  const topGPData = useMemo(() => {
    const clientGroups = data.reduce((acc, curr) => {
      const name = curr['nombre cliente'];
      if (acc[name] === undefined) acc[name] = 0;
      acc[name] = (acc[name] as number) + curr.GP;
      return acc;
    }, {} as Record<string, number>);

    return Object.entries(clientGroups)
      .map(([name, gp]) => ({ name, gp: gp as number }))
      .sort((a, b) => (b.gp as number) - (a.gp as number))
      .slice(0, 10);
  }, [data]);

  // 5. Inversión por Clasificación - Promedio basado solo en clientes con inversión
  const classificationData = useMemo(() => {
    const groups: Record<string, { total: number; count: number }> = {};
    data.forEach(item => {
      const cls = item.clasificacion || 'N/A';
      const inv = item.totalInversion || 0;
      if (!groups[cls]) groups[cls] = { total: 0, count: 0 };

      const group = groups[cls]!;
      group.total += inv;
      if (inv > 0) {
        group.count += 1;
      }
    });

    return Object.entries(groups).map(([name, stats]) => ({
      name: `Clase ${name}`,
      avg: stats.count > 0 ? stats.total / stats.count : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
  }, [data]);

  const formatCurrency = (value: number) => `$${value.toLocaleString(undefined, {minimumFractionDigits: 0, maximumFractionDigits: 0})}`;

  return (
    <div className="space-y-8">
      {/* Fila 1: Tendencias */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-blue-600 rounded-full"></span>
            Utilidad Bruta Mensual (GP)
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorGp" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip formatter={(value: number) => [formatCurrency(value), "GP"]} />
                <Area type="monotone" dataKey="gp" stroke="#2563eb" strokeWidth={3} fill="url(#colorGp)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-violet-500 rounded-full"></span>
            Inversión Total por Mes (Q)
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={trendData} margin={{ left: 10, right: 10 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis 
                  axisLine={true} 
                  tickLine={true} 
                  tick={{fontSize: 10, fill: '#64748b'}} 
                  width={60}
                  domain={[0, 'auto']}
                  tickFormatter={(v) => v >= 1000 ? `$${(v/1000).toFixed(1)}k` : `$${v}`}
                />
                <Tooltip formatter={(value: number) => [formatCurrency(value), "Inversión"]} />
                <Bar dataKey="labInv" fill="#8b5cf6" radius={[6, 6, 0, 0]} barSize={35} />
                {avgLabInv > 0 && (
                  <ReferenceLine 
                    y={avgLabInv} 
                    stroke="#4f46e5" 
                    strokeDasharray="5 5" 
                    strokeWidth={2}
                  >
                    <Label 
                      value={`PROM: ${formatCurrency(avgLabInv)}`} 
                      position="top" 
                      fill="#4f46e5"
                      style={{ fontSize: 11, fontWeight: '800', backgroundColor: 'white' }} 
                    />
                  </ReferenceLine>
                )}
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Fila 2: Distribución y Clases */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-emerald-500 rounded-full"></span>
            Desglose de Activos de Inversión
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={distributionData}
                  cx="50%" cy="45%" innerRadius={60} outerRadius={85} paddingAngle={5}
                  dataKey="value"
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                >
                  {distributionData.map((entry, index) => <Cell key={index} fill={entry.color} />)}
                </Pie>
                <Tooltip formatter={(v: number) => formatCurrency(v)} />
                <Legend verticalAlign="bottom" iconType="circle" />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-indigo-500 rounded-full"></span>
            Inversión Promedio por Clase
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={classificationData} margin={{ top: 20 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 11, fill: '#64748b'}} />
                <YAxis hide />
                <Tooltip formatter={(v: number) => formatCurrency(v)} />
                <Bar dataKey="avg" fill="#6366f1" radius={[8, 8, 0, 0]} barSize={45}>
                  <LabelList dataKey="avg" position="top" formatter={(v: number) => `$${Math.round(v/1000)}k`} style={{fontSize: 10, fill: '#6366f1', fontWeight: 'bold'}} />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Fila 3: Ratios y Top Clientes GP (Lado a Lado) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[450px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-rose-500 rounded-full"></span>
            Ratio de Inversión por Cliente (% Utilidad)
          </h3>
          <div className="flex-1">
            {riskData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={riskData} layout="vertical" margin={{ left: 30, right: 40 }}>
                  <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                  <XAxis type="number" hide />
                  <YAxis dataKey="name" type="category" width={120} tick={{fontSize: 9, fill: '#64748b'}} axisLine={false} tickLine={false} />
                  <Tooltip formatter={(v: number) => [`${v.toFixed(2)}%`, "Ratio"]} />
                  <Bar dataKey="ratio" radius={[0, 4, 4, 0]} barSize={15}>
                    {riskData.map((entry, index) => (
                      <Cell key={index} fill={entry.rawRatio > 8 ? '#f43f5e' : '#cbd5e1'} />
                    ))}
                    <LabelList dataKey="ratio" position="right" formatter={(v: number) => `${v.toFixed(2)}%`} style={{fontSize: 9, fill: '#64748b', fontWeight: 'bold'}} />
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="flex h-full items-center justify-center text-slate-400 italic text-sm">Sin datos para mostrar.</div>
            )}
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[450px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-emerald-600 rounded-full"></span>
            Top 10 Clientes por Utilidad Bruta (GP)
          </h3>
          <div className="flex-1">
            {topGPData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={topGPData} layout="vertical" margin={{ left: 30, right: 60 }}>
                  <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                  <XAxis type="number" hide />
                  <YAxis dataKey="name" type="category" width={120} tick={{fontSize: 9, fill: '#64748b'}} axisLine={false} tickLine={false} />
                  <Tooltip formatter={(v: number) => [formatCurrency(v), "Utilidad Bruta"]} />
                  <Bar dataKey="gp" fill="#059669" radius={[0, 4, 4, 0]} barSize={15}>
                    <LabelList dataKey="gp" position="right" formatter={(v: number) => `$${Math.round(v/1000)}k`} style={{fontSize: 9, fill: '#059669', fontWeight: 'bold'}} />
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="flex h-full items-center justify-center text-slate-400 italic text-sm">Sin datos para mostrar.</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { FinancialRecord } from '../types';
import { Weight, DollarSign, TrendingUp, FlaskConical, Target, Activity } from 'lucide-react';

interface KPIsProps {
  data: FinancialRecord[];
}

export const KPIs: React.FC<KPIsProps> = ({ data }) => {
  // Función de suma que incluye ABSOLUTAMENTE todos los datos del array filtrado
  const sumAll = (key: keyof FinancialRecord) => 
    data.reduce((acc, curr) => {
      const val = curr[key];
      return acc + (typeof val === 'number' ? val : 0);
    }, 0);

  const totalTons = sumAll('TON');
  const totalTurnover = sumAll('TURN OVER'); // Columna H
  const totalGM = sumAll('GM'); // Columna J
  const totalGP = sumAll('GP'); // Columna L
  const totalInv = sumAll('totalInversion'); // Columna Q

  // ÍNDICE REAL GLOBAL: (Sum(Q) / Sum(L)) * 100
  const globalRatio = totalGP !== 0 ? (totalInv / totalGP) * 100 : 0;

  // Formato con precisión ajustada
  const formatAdjustedPrecision = (val: number) => {
    const absVal = Math.abs(val);
    if (absVal >= 1000000) {
      return `$${(val / 1000000).toLocaleString(undefined, { minimumFractionDigits: 3, maximumFractionDigits: 3 })}M`;
    }
    if (absVal >= 1000) {
      return `$${(val / 1000).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}k`;
    }
    return `$${val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const kpiList = [
    { 
      label: 'Ton. Métricas', 
      value: Math.round(totalTons).toLocaleString(), 
      sub: 'Volumen Bruto (TON)', 
      icon: Weight, 
      color: 'bg-amber-500' 
    },
    { 
      label: 'Turn Over', 
      value: formatAdjustedPrecision(totalTurnover), 
      sub: 'Ventas Totales (Col H)', 
      icon: Activity, 
      color: 'bg-cyan-600' 
    },
    { 
      label: 'Margen Bruto', 
      value: formatAdjustedPrecision(totalGM), 
      sub: 'Total Columna J (GM)', 
      icon: DollarSign, 
      color: 'bg-emerald-500' 
    },
    { 
      label: 'Utilidad Bruta', 
      value: formatAdjustedPrecision(totalGP), 
      sub: 'Total Columna L (GP)', 
      icon: TrendingUp, 
      color: 'bg-blue-600' 
    },
    { 
      label: 'Inversión Lab', 
      value: formatAdjustedPrecision(totalInv), 
      sub: 'Total Columna Q (INV)', 
      icon: FlaskConical, 
      color: 'bg-violet-600' 
    },
    { 
      label: 'Índice Real', 
      value: globalRatio.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%', 
      sub: 'Ratio Global (Q/L)*100', 
      icon: Target, 
      color: 'bg-teal-600' 
    },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
      {kpiList.map((kpi, idx) => (
        <div key={idx} className={`${kpi.color} p-5 rounded-2xl shadow-xl shadow-slate-200/50 text-white flex flex-col justify-between transform hover:-translate-y-1 transition-all duration-300`}>
          <div className="flex justify-between items-start mb-4">
            <div className="p-2 bg-white/20 rounded-xl">
              <kpi.icon size={20} />
            </div>
            <span className="text-[10px] font-bold uppercase tracking-widest opacity-70">
              {kpi.sub}
            </span>
          </div>
          <div>
            <p className="text-2xl font-extrabold tracking-tight leading-none mb-1">{kpi.value}</p>
            <h3 className="text-xs font-semibold opacity-90">{kpi.label}</h3>
          </div>
        </div>
      ))}
    </div>
  );
};

