                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} tickFormatter={(v) => `$${Math.round(v/1000)}k`} />
                <Tooltip formatter={(value: number) => [formatCurrency(value), "GP"]} />
                <Area type="monotone" dataKey="gp" stroke="#2563eb" strokeWidth={3} fill="url(#colorGp)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Turn Over Chart (Nuevo) */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-cyan-600 rounded-full"></span>
            Turn Over Mensual (Ventas)
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData}>
                <defs>
                  <linearGradient id="colorTurnover" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#0891b2" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#0891b2" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fontSize: 10, fill: '#94a3b8'}} 
                  width={40}
                  tickFormatter={(v) => v >= 1000000 ? `$${(v/1000000).toFixed(0)}M` : `$${Math.round(v/1000)}k`} 
                />
                <Tooltip formatter={(value: number) => [formatCurrency(value), "Turn Over"]} />
                <Area type="monotone" dataKey="turnover" stroke="#0891b2" strokeWidth={3} fill="url(#colorTurnover)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Fila 2: Inversión (Total y Distribución) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Inversión Total (Movido) */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-violet-500 rounded-full"></span>
            Inversión Total por Mes (Q)
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={trendData} margin={{ left: 10, right: 10 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis 
                  axisLine={true} 
                  tickLine={true} 
                  tick={{fontSize: 10, fill: '#64748b'}} 
                  width={60}
                  domain={[0, 'auto']}
                  tickFormatter={(v) => v >= 1000 ? `$${(v/1000).toFixed(1)}k` : `$${v}`}
                />
                <Tooltip formatter={(value: number) => [formatCurrency(value), "Inversión"]} />
                <Bar dataKey="labInv" fill="#8b5cf6" radius={[6, 6, 0, 0]} barSize={35} />
                {avgLabInv > 0 && (
                  <ReferenceLine 
                    y={avgLabInv} 
                    stroke="#4f46e5" 
                    strokeDasharray="5 5" 
                    strokeWidth={2}
                  >
                    <Label 
                      value={`PROM: ${formatCurrency(avgLabInv)}`} 
                      position="top" 
                      fill="#4f46e5"
                      style={{ fontSize: 11, fontWeight: '800', backgroundColor: 'white' }} 
                    />
                  </ReferenceLine>
                )}
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Desglose de Inversión (Pie) */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-emerald-500 rounded-full"></span>
            Desglose de Activos de Inversión
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={distributionData}
                  cx="50%" cy="45%" innerRadius={60} outerRadius={85} paddingAngle={5}
                  dataKey="value"
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                >
                  {distributionData.map((entry, index) => <Cell key={index} fill={entry.color} />)}
                </Pie>
                <Tooltip formatter={(v: number) => formatCurrency(v)} />
                <Legend verticalAlign="bottom" iconType="circle" />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Fila 3: Clases y Ratios */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-indigo-500 rounded-full"></span>
            Inversión Promedio por Clase
          </h3>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={classificationData} margin={{ top: 20 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 11, fill: '#64748b'}} />
                <YAxis hide />
                <Tooltip formatter={(v: number) => formatCurrency(v)} />
                <Bar dataKey="avg" fill="#6366f1" radius={[8, 8, 0, 0]} barSize={45}>
