import React, { useState, useEffect, useMemo } from 'react';
import { FinancialRecord } from '../types.ts';
import { MONTHS } from '../utils/dataProcessor.ts';
import { Filter, Upload, RotateCcw, Calendar, ChevronLeft, Search, X, Clock } from 'lucide-react';
import * as XLSX from 'xlsx';

interface SidebarProps {
  allData: FinancialRecord[];
  onFilterChange: (filters: any) => void;
  onDataUpload: (data: any[]) => void;
  onClose?: () => void;
  isOpen?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({ allData, onFilterChange, onDataUpload, onClose, isOpen }) => {
  const [selectedYears, setSelectedYears] = useState<string[]>([]);
  const [client, setClient] = useState('all');
  const [clientSearch, setClientSearch] = useState('');
  const [classification, setClassification] = useState('all');
  const [selectedMonths, setSelectedMonths] = useState<string[]>([]);

  const years = useMemo(() => Array.from(new Set(allData.map(d => d.año))).sort((a: number, b: number) => b - a), [allData]);
  const allClients = useMemo(() => Array.from(new Set(allData.map(d => d['nombre cliente']))).sort(), [allData]);
  const classifications = useMemo(() => Array.from(new Set(allData.map(d => d.clasificacion))).filter(Boolean).sort(), [allData]);

  const filteredClients = useMemo(() => {
    if (!clientSearch.trim()) return allClients;
    return allClients.filter(c => 
      c.toLowerCase().includes(clientSearch.toLowerCase())
    );
  }, [allClients, clientSearch]);

  useEffect(() => {
    onFilterChange({ 
      years: selectedYears,
      client, 
      classification, 
      months: selectedMonths 
    });
  }, [selectedYears, client, classification, selectedMonths]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const bstr = event.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json(ws);
      onDataUpload(data);
    };
    reader.readAsBinaryString(file);
  };

  const toggleYear = (y: string) => {
    setSelectedYears(prev => 
      prev.includes(y) ? prev.filter(year => year !== y) : [...prev, y]
    );
  };

  const toggleAllYears = () => {
    if (selectedYears.length === years.length) {
      setSelectedYears([]);
    } else {
      setSelectedYears(years.map(y => y.toString()));
    }
  };

  const toggleMonth = (m: string) => {
    setSelectedMonths(prev => 
      prev.includes(m) ? prev.filter(month => month !== m) : [...prev, m]
    );
  };

  const toggleAllMonths = () => {
    if (selectedMonths.length === MONTHS.length) {
      setSelectedMonths([]);
    } else {
      setSelectedMonths([...MONTHS]);
    }
  };

  const resetFilters = () => {
    setSelectedYears([]);
    setClient('all');
    setClientSearch('');
    setClassification('all');
    setSelectedMonths([]);
  };

  const clearSearch = () => {
    setClientSearch('');
  };

  return (
    <aside className={`w-80 bg-white border-r border-slate-200 flex flex-col h-full shadow-xl z-20 overflow-hidden transition-all duration-300`}>
      <div className="p-6 space-y-8 flex-1 overflow-y-auto no-scrollbar">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Configuración</h2>
            <div className="flex items-center gap-2 text-slate-800">
              <Filter size={20} className="text-blue-600" />
              <span className="font-bold text-lg">Filtros y Datos</span>
            </div>
          </div>
          {onClose && (
            <button 
              onClick={onClose}
              className="p-2 hover:bg-slate-100 rounded-lg text-slate-400 lg:hidden"
            >
              <ChevronLeft size={20} />
            </button>
          )}
        </div>

        <div className="space-y-3">
          <label className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2">
            <Upload size={14} /> Importar Datos (Excel)
          </label>
          <div className="relative group">
            <input 
              type="file" 
              accept=".xlsx,.xls,.csv" 
              onChange={handleFileUpload}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
            />
            <div className="border-2 border-dashed border-slate-200 group-hover:border-blue-400 group-hover:bg-blue-50 transition-all rounded-xl p-4 text-center">
              <span className="text-xs font-semibold text-slate-500 group-hover:text-blue-600 transition-colors">
                Arrastre archivo o haga clic
              </span>
            </div>
          </div>
        </div>

        <div className="space-y-6">
          <div className="space-y-3">
             <div className="flex items-center justify-between">
              <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest flex items-center gap-1">
                <Clock size={10} /> Años de Análisis
              </label>
              <button 
                onClick={toggleAllYears}
                className="text-[9px] font-bold text-blue-600 hover:underline uppercase tracking-tighter"
              >
                {selectedYears.length === years.length ? 'Limpiar' : 'Seleccionar Todos'}
              </button>
            </div>
            <div className="grid grid-cols-3 gap-1.5">
              {years.map(y => {
                const yStr = y.toString();
                const isSelected = selectedYears.includes(yStr);
                return (
                  <button
                    key={y}
                    onClick={() => toggleYear(yStr)}
                    className={`py-2 px-1 text-[11px] font-bold rounded-md border transition-all truncate ${
                      isSelected 
                        ? 'bg-slate-800 border-slate-800 text-white shadow-md shadow-slate-200' 
                        : 'bg-white border-slate-100 text-slate-500 hover:border-slate-300 hover:bg-slate-50'
                    }`}
                  >
                    {y}
                  </button>
                );
              })}
            </div>
          </div>

          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest flex items-center gap-1">
                <Calendar size={10} /> Selección de Meses
              </label>
              <button 
                onClick={toggleAllMonths}
                className="text-[9px] font-bold text-blue-600 hover:underline uppercase tracking-tighter"
              >
                {selectedMonths.length === MONTHS.length ? 'Limpiar' : 'Seleccionar Todos'}
              </button>
            </div>
            <div className="grid grid-cols-3 gap-1.5">
              {MONTHS.map(m => {
                const isSelected = selectedMonths.includes(m);
                return (
                  <button
                    key={m}
                    onClick={() => toggleMonth(m)}
                    className={`py-2 px-1 text-[10px] font-bold rounded-md border transition-all truncate ${
                      isSelected 
                        ? 'bg-blue-600 border-blue-600 text-white shadow-md shadow-blue-200' 
                        : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300 hover:bg-slate-50'
                    }`}
                  >
                    {m.substring(0, 3)}
                  </button>
                );
              })}
            </div>
          </div>

          <div className="space-y-3">
            <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Filtro de Cliente</label>
            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400 group-focus-within:text-blue-500 transition-colors">
                <Search size={14} />
              </div>
              <input 
                type="text"
                placeholder="Escriba para buscar..."
                value={clientSearch}
                onChange={(e) => setClientSearch(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg pl-9 pr-8 py-2 text-xs font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
              />
              {clientSearch && (
                <button 
                  onClick={clearSearch}
                  className="absolute inset-y-0 right-0 pr-3 flex items-center text-slate-400 hover:text-rose-500 transition-colors"
                >
                  <X size={14} />
                </button>
              )}
            </div>
            <select 
              value={client} 
              onChange={(e) => setClient(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            >
              <option value="all">Consolidado (Ver Todos)</option>
              {filteredClients.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Clasificación</label>
            <select 
              value={classification} 
              onChange={(e) => setClassification(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            >
              <option value="all">Todas las categorías</option>
              {classifications.map(c => <option key={c} value={c}>Clase {c}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="p-6 border-t border-slate-100 bg-slate-50">
        <button 
          onClick={resetFilters}
          className="w-full flex items-center justify-center gap-2 bg-slate-800 text-white p-3 rounded-xl font-bold text-sm hover:bg-slate-900 transition-all shadow-lg active:scale-95"
        >
          <RotateCcw size={16} />
          Limpiar Filtros
        </button>
      </div>
    </aside>
  );
};

import React from 'react';
import { FinancialRecord } from '../types.ts';
import { Weight, DollarSign, TrendingUp, FlaskConical, Target, Activity } from 'lucide-react';

interface KPIsProps {
  data: FinancialRecord[];
}

export const KPIs: React.FC<KPIsProps> = ({ data }) => {
  const sumAll = (key: keyof FinancialRecord) => 
    data.reduce((acc, curr) => {
      const val = curr[key];
      return acc + (typeof val === 'number' ? val : 0);
    }, 0);

  const totalTons = sumAll('TON');
  const totalTurnover = sumAll('TURN OVER');
  const totalGM = sumAll('GM');
  const totalGP = sumAll('GP');
  const totalInv = sumAll('totalInversion');

  const globalRatio = totalGP !== 0 ? (totalInv / totalGP) * 100 : 0;

  const formatAdjustedPrecision = (val: number) => {
    const absVal = Math.abs(val);
    if (absVal >= 1000000) {
      return `$${(val / 1000000).toLocaleString(undefined, { minimumFractionDigits: 3, maximumFractionDigits: 3 })}M`;
    }
    if (absVal >= 1000) {
      return `$${(val / 1000).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}k`;
    }
    return `$${val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const kpiList = [
    { label: 'Ton. Métricas', value: Math.round(totalTons).toLocaleString(), sub: 'Volumen Bruto (TON)', icon: Weight, color: 'bg-amber-500' },
    { label: 'Turn Over', value: formatAdjustedPrecision(totalTurnover), sub: 'Ventas Totales (Col H)', icon: Activity, color: 'bg-cyan-600' },
    { label: 'Margen Bruto', value: formatAdjustedPrecision(totalGM), sub: 'Total Columna J (GM)', icon: DollarSign, color: 'bg-emerald-500' },
    { label: 'Utilidad Bruta', value: formatAdjustedPrecision(totalGP), sub: 'Total Columna L (GP)', icon: TrendingUp, color: 'bg-blue-600' },
    { label: 'Inversión Lab', value: formatAdjustedPrecision(totalInv), sub: 'Total Columna Q (INV)', icon: FlaskConical, color: 'bg-violet-600' },
    { label: 'Índice Real', value: globalRatio.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%', sub: 'Ratio Global (Q/L)*100', icon: Target, color: 'bg-teal-600' },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
      {kpiList.map((kpi, idx) => (
        <div key={idx} className={`${kpi.color} p-5 rounded-2xl shadow-xl shadow-slate-200/50 text-white flex flex-col justify-between transform hover:-translate-y-1 transition-all duration-300`}>
          <div className="flex justify-between items-start mb-4">
            <div className="p-2 bg-white/20 rounded-xl">
              <kpi.icon size={20} />
            </div>
            <span className="text-[10px] font-bold uppercase tracking-widest opacity-70">
              {kpi.sub}
            </span>
          </div>
          <div>
            <p className="text-2xl font-extrabold tracking-tight leading-none mb-1">{kpi.value}</p>
            <h3 className="text-xs font-semibold opacity-90">{kpi.label}</h3>
          </div>
        </div>
      ))}
    </div>
  );
};

import React, { useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Legend, Cell, PieChart, Pie, LabelList, ReferenceLine, Label
} from 'recharts';
import { FinancialRecord } from '../types.ts';
import { MONTHS } from '../utils/dataProcessor.ts';

interface ChartsProps {data: FinancialRecord[];}

export const Charts: React.FC<ChartsProps> = ({ data }) => {
  // 1. Tendencia Mensual
  const trendData = useMemo(() => {
    return MONTHS.map(m => {
      const recordsInMonth = data.filter(d => d.Fecha.toUpperCase() === m);
      return {
        month: m.substring(0, 3),
        gp: recordsInMonth.reduce((acc, curr) => acc + curr.GP, 0),
        labInv: recordsInMonth.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0),
        ton: recordsInMonth.reduce((acc, curr) => acc + curr.TON, 0),
      };
    }).filter(d => d.gp !== 0 || d.labInv !== 0 || d.ton !== 0);
  }, [data]);

  // Promedio inversión mensual
  const avgLabInv = useMemo(() => {
    if (trendData.length === 0) return 0;
    const total = trendData.reduce((acc, curr) => acc + curr.labInv, 0);
    return total / trendData.length;
  }, [trendData]);

  // 2. Distribución de Inversión
  const distributionData = useMemo(() => {
    const lab = data.reduce((acc, curr) => acc + curr['inversion analisis lab'], 0);
    const nir = data.reduce((acc, curr) => acc + curr['Inversion Nir'], 0);
    const mico = data.reduce((acc, curr) => acc + curr['Inversion equipos Micotoxinas'], 0);
    return [
      { name: 'Lab Análisis', value: lab, color: '#3b82f6' },
      { name: 'NIR', value: nir, color: '#10b981' },
      { name: 'Micotoxinas', value: mico, color: '#f59e0b' }
    ].filter(d => d.value > 0);
  }, [data]);

  // 3. Ratios por Cliente
  const riskData = useMemo(() => {
    const clientGroups = data.reduce((acc, curr) => {
      const name = curr['nombre cliente'];
      if (!acc[name]) acc[name] = { gp: 0, inv: 0 };
      const group = acc[name]!;
      group.gp += curr.GP;
      group.inv += (curr.totalInversion || 0);
      return acc;
    }, {} as Record<string, { gp: number; inv: number }>);

    return Object.keys(clientGroups)
      .map(name => {
        const group = clientGroups[name]!;
        const rawRatio = group.gp !== 0 ? (group.inv / group.gp) * 100 : 0;
        return { name, ratio: rawRatio, rawRatio };
      })
      .sort((a, b) => b.ratio - a.ratio)
      .slice(0, 10);
  }, [data]);

  // 4. Top 10 Clientes por GP
  const topGPData = useMemo(() => {
    const clientGroups = data.reduce((acc, curr) => {
      const name = curr['nombre cliente'];
      if (acc[name] === undefined) acc[name] = 0;
      acc[name] = (acc[name] as number) + curr.GP;
      return acc;
    }, {} as Record<string, number>);

    return Object.entries(clientGroups)
      .map(([name, gp]) => ({ name, gp: gp as number }))
      .sort((a, b) => (b.gp as number) - (a.gp as number))
      .slice(0, 10);
  }, [data]);

  // 5. Inversión por Clasificación
  const classificationData = useMemo(() => {
    const groups: Record<string, { total: number; count: number }> = {};
    data.forEach(item => {
      const cls = item.clasificacion || 'N/A';
      const inv = item.totalInversion || 0;
      if (!groups[cls]) groups[cls] = { total: 0, count: 0 };

      const group = groups[cls]!;
      group.total += inv;
      if (inv > 0) {
        group.count += 1;
      }
    });

    return Object.entries(groups).map(([name, stats]) => ({
      name: `Clase ${name}`,
      avg: stats.count > 0 ? stats.total / stats.count : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
  }, [data]);

  // Conteo de clientes únicos por categoría y total global
  const { categoryCounts, totalUniqueClients } = useMemo(() => {
    const counts: Record<string, Set<string>> = {};
    const allUniqueClients = new Set<string>();

    data.forEach(item => {
      const cls = item.clasificacion || 'N/A';
      const client = item['nombre cliente'];
      if (!counts[cls]) counts[cls] = new Set();
      counts[cls].add(client);
      allUniqueClients.add(client);
    });

    const categoryCountsArray = Object.entries(counts).map(([name, clients]) => ({
      name: `Clase ${name}`,
      count: clients.size
    })).sort((a, b) => a.name.localeCompare(b.name));

    return {
      categoryCounts: categoryCountsArray,
      totalUniqueClients: allUniqueClients.size
    };
  }, [data]);

  const formatCurrency = (value: number) => `$${value.toLocaleString(undefined, {minimumFractionDigits: 0, maximumFractionDigits: 0})}`;

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 gap-8">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-[380px] flex flex-col">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-2 h-2 bg-blue-600 rounded-full"></span>
            Utilidad Bruta Mensual (GP)
          </h3>
