import { GoogleGenAI } from "@google/genai";
import { FinancialRecord } from "../types.ts";

export const generateBusinessInsights = async (data: FinancialRecord[]): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const summaryData = data.slice(0, 15).map(item => ({
      cliente: item['nombre cliente'],
      utilidad: item.GP,
      toneladas: item.TON,
      ratio: (item['% Inversion Lab'] || 0) * 100
    }));

    const totalGP = data.reduce((acc, curr) => acc + curr.GP, 0);
    const totalInv = data.reduce((acc, curr) => acc + (curr.totalInversion || 0), 0);
    const globalRatio = totalGP > 0 ? (totalInv / totalGP) * 100 : 0;

    const prompt = `
      Actúa como un Analista Financiero Senior. Analiza estos datos de rendimiento empresarial:
      - Cantidad de registros: ${data.length}
      - Utilidad Bruta Total (GP): $${totalGP.toLocaleString()}
      - Inversión Total: $${totalInv.toLocaleString()}
      - Ratio Global de Inversión: ${globalRatio.toFixed(2)}%

      Muestra de Rendimiento por Cliente:
      ${JSON.stringify(summaryData)}

      Por favor, responde en ESPAÑOL y proporciona:
      1. Un resumen conciso de la salud financiera actual.
      2. Identificación de clientes de alto riesgo (donde el ratio de inversión supere el 8%).
      3. Recomendaciones estratégicas accionables para mejorar el retorno de inversión (ROI).

      Utiliza un formato Markdown profesional. Mantén la respuesta breve y de alto impacto.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
    });

    return response.text || "No se han podido generar análisis en este momento.";
  } catch (error) {
    console.error("Error en API Gemini:", error);
    return "Error al generar el análisis. Por favor, asegúrese de que su clave de API es válida.";
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { Sidebar } from './components/Sidebar.tsx';
import { KPIs } from './components/KPIs.tsx';
import { Charts } from './components/Charts.tsx';
import { DataTable } from './components/DataTable.tsx';
import { FinancialRecord } from './types.ts';
import { processRawData, getBackupData } from './utils/dataProcessor.ts';
import { LayoutDashboard, Menu, X } from 'lucide-react';

const App: React.FC = () => {
  const [allData, setAllData] = useState<FinancialRecord[]>([]);
  const [filteredData, setFilteredData] = useState<FinancialRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // Initialize with backup data
  useEffect(() => {
    const data = processRawData(getBackupData());
    setAllData(data);
    setFilteredData(data);
    setIsLoading(false);
  }, []);

  const handleDataUpdate = (newData: any[]) => {
    setIsLoading(true);
    const processed = processRawData(newData);
    setAllData(processed);
    setFilteredData(processed);
    setIsLoading(false);
  };

  const handleFilterChange = (filters: {
    years: string[];
    client: string;
    classification: string;
    months: string[];
  }) => {
    const filtered = allData.filter((item) => {
      const yearMatch = filters.years.length === 0 || filters.years.includes(item.año.toString());
      const clientMatch = filters.client === 'all' || item['nombre cliente'] === filters.client;
      const classMatch = filters.classification === 'all' || item.clasificacion === filters.classification;
      const monthMatch = filters.months.length === 0 || filters.months.includes(item.Fecha.toUpperCase());
      return yearMatch && clientMatch && classMatch && monthMatch;
    });
    setFilteredData(filtered);
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden text-slate-900">
      <div className={`fixed inset-y-0 left-0 z-30 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 transition-all duration-300 ease-in-out`}>
        <Sidebar 
          allData={allData} 
          onFilterChange={handleFilterChange} 
          onDataUpload={handleDataUpdate}
          onClose={() => setIsSidebarOpen(false)}
          isOpen={isSidebarOpen}
        />
      </div>

      <main className="flex-1 flex flex-col overflow-hidden w-full">
        <header className="bg-white border-b border-slate-200 px-8 py-4 flex items-center justify-between shadow-sm z-10">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-100 rounded-lg transition-colors text-slate-600 lg:hidden"
            >
              <Menu size={24} />
            </button>
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-100 rounded-lg transition-colors text-slate-600 hidden lg:block"
            >
              {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-lg">
                <LayoutDashboard className="text-white w-6 h-6" />
              </div>
              <div>
                <h1 className="text-[22px] font-bold text-slate-800 leading-tight">Pilar Control Laboratorio</h1>
                <p className="text-xs text-slate-500 font-medium">Panel de Rendimiento Empresarial</p>
              </div>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-4">
            <div className="text-right">
              <span className="text-xs text-slate-400 block uppercase tracking-wider font-bold">Estado de Datos</span>
              <span className="text-sm font-semibold text-emerald-600 flex items-center gap-1">
                <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                Dataset Activo
              </span>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
          {isLoading ? (
            <div className="flex items-center justify-center h-full">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
          ) : (
            <>
              <KPIs data={filteredData} />
              <Charts data={filteredData} />
              <div className="w-full">
                <DataTable data={filteredData} />
              </div>
            </>
          )}
        </div>
      </main>

      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/20 z-20 lg:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

